insert into candidate_positions (id, candidate_id, question_id, answer_type, numeric_score, option_id, option_ids, explanation, source_url, source_name, verified_at) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:position:pos-nicolas-dupont-aignan-q16-81'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nicolas-dupont-aignan'), uuid_generate_v5(uuid_ns_url(), 'poliscope:question:q16'), 'likert', -2, null, null, 'Son « projet européen » prévoit de supprimer la Commission européenne et la CJUE et d''affirmer la primauté du droit français.', 'https://www.debout-la-france.fr/actualite/discours-de-rentree-les-10-points-du-projet-europeen-pour-une-france-libre-au-service-dun-monde-libre/', 'Debout la France', null) on conflict (id) do nothing;
