insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:jean-luc-melenchon'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:retraites'), 'Abroger la réforme Macron et retraite à 60 ans', 'Abroger la réforme des retraites de 2023 et restaurer le droit à la retraite à 60 ans.', 'Le programme prévoit d''abroger la réforme portant l''âge légal à 64 ans, de restaurer la retraite à 60 ans pour une carrière complète (40 annuités), et de porter les pensions au niveau du SMIC revalorisé.', 'Programme « L''Avenir en commun » 2025 — chapitre 8', 'https://melenchon2027.fr/programme2025/livre/chapitre8/s8/', '2025-01-01', '2026-09-09', 'programme', 'Âge légal, Réforme des retraites') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-2'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:jean-luc-melenchon'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:pouvoir-achat'), 'SMIC à 1 600 euros net et blocage des prix', 'Augmenter immédiatement le SMIC à 1 600 euros net et bloquer les prix des produits de première nécessité.', 'Dans le cadre d''un « état d''urgence sociale », le programme propose une hausse immédiate du SMIC et des minima sociaux, un blocage des prix de l''alimentation, de l''énergie et du carburant, et une interdiction de la « réduflation ».', 'Programme « L''Avenir en commun » 2025 — chapitre 9', 'https://melenchon2027.fr/programme2025/livre/chapitre9/s1/', '2025-01-01', '2026-09-09', 'programme', 'SMIC, Prix') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-3'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:jean-luc-melenchon'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:immigration'), 'Régularisation et politique migratoire humaniste', 'Régulariser travailleurs, étudiants et parents d''enfants scolarisés sans papiers.', 'Le programme propose de faciliter l''accès aux visas, de régulariser certaines catégories de personnes sans papiers, de suspendre le règlement de Dublin et de renégocier les accords du Touquet.', 'Programme « L''Avenir en commun » 2025 — chapitre 16', 'https://melenchon2027.fr/programme2025/livre/chapitre16/s7/', '2025-01-01', '2026-09-09', 'programme', 'Régularisation, Asile') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-4'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:jean-luc-melenchon'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:securite'), 'Refonder une police républicaine de proximité', 'Réorganiser la police autour de la proximité et interdire certaines armes et technologies.', 'Extension de la formation des policiers, interdiction d''armes comme le Taser et le Flash-Ball, des techniques d''immobilisation mortelles et de la reconnaissance faciale, et dissolution de certaines unités (BAC, BRAV-M).', 'Programme « L''Avenir en commun » 2025 — chapitre 4', 'https://melenchon2027.fr/programme2025/livre/chapitre4/s3/', '2025-01-01', '2026-09-09', 'programme', 'Police, Réforme policière') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-5'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:jean-luc-melenchon'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:sante'), 'Réouverture d''urgences et 100 % Sécurité sociale', 'Rouvrir urgences, maternités et EHPAD publics fermés depuis 2010.', 'Plan pluriannuel de recrutement de soignants, remplacement de l''ONDAM par un objectif fondé sur les besoins de santé, garantie d''un service d''urgence à moins de 30 minutes de tout Français.', 'Programme « L''Avenir en commun » 2025 — chapitre 15', 'https://melenchon2027.fr/programme2025/livre/chapitre15/s2/', '2025-01-01', '2026-09-09', 'programme', 'Hôpital public, Urgences') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-6'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:jean-luc-melenchon'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:education'), 'Gratuité réelle de l''école et réduction des effectifs', 'Assurer la gratuité complète de l''école publique et réduire les effectifs par classe.', 'Réduction des effectifs sous la moyenne européenne de 19 élèves, priorité en maternelle et zones prioritaires, création d''écoles professionnelles pour la formation des enseignants et revalorisation salariale.', 'Programme « L''Avenir en commun » 2025 — chapitre 5', 'https://melenchon2027.fr/programme2025/livre/chapitre5/s3/', '2025-01-01', '2026-09-09', 'programme', 'Effectifs, Gratuité') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-7'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:jean-luc-melenchon'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:energie'), '100 % renouvelable et sortie du nucléaire', 'Planifier le passage à 100 % d''énergies renouvelables d''ici 2050 et sortir du nucléaire.', 'Abandon des projets d''EPR, démantèlement progressif des sites nucléaires avec reconversion des salariés, création d''un pôle public de l''énergie, tarifs réglementés et rénovation d''au moins 700 000 logements par an.', 'Programme « L''Avenir en commun » 2025 — chapitre 13', 'https://melenchon2027.fr/programme2025/livre/chapitre13/s3/', '2025-01-01', '2026-09-09', 'programme', 'Renouvelables, Nucléaire') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-8'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:jean-luc-melenchon'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:europe'), 'Désobéissance aux traités et « Plan B » européen', 'Renégocier les traités européens ou appliquer unilatéralement le programme national en cas d''échec.', 'Désobéir aux règles européennes jugées bloquantes, récupérer la souveraineté budgétaire, modifier le statut de la BCE, et instaurer un protectionnisme écologique aux frontières de l''UE.', 'Programme « L''Avenir en commun » 2025 — chapitre 17', 'https://melenchon2027.fr/programme2025/livre/chapitre17/', '2025-01-01', '2026-09-09', 'programme', 'Traités européens, Souveraineté') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-9'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:jean-luc-melenchon'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:logement'), '200 000 logements publics par an et encadrement des loyers', 'Construire 200 000 logements publics par an et encadrer les loyers sur tout le territoire.', 'Abrogation de la loi Kasbarian, interdiction des expulsions locatives sans relogement, garantie universelle des loyers, et obligation de rénovation thermique avant mise en location.', 'Programme « L''Avenir en commun » 2025 — chapitre 7', 'https://melenchon2027.fr/programme2025/livre/chapitre7/s5/', '2025-01-01', '2026-09-09', 'programme', 'Logement social, Loyers') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-10'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:jean-luc-melenchon'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:economie'), 'Geler une partie de la dette française détenue par la BCE', 'Propose que la BCE transforme la dette publique française qu''elle détient en dette perpétuelle à taux nul plutôt que de l''annuler.', 'Lors du discours de clôture des universités d''été de La France insoumise le 23 août 2026, il propose que la Banque centrale européenne transforme en « dette perpétuelle à taux nul » la dette française qu''elle détient, en particulier celle issue de la période Covid, pour dégager des marges budgétaires ; il chiffre le montant concerné à 636 milliards d''euros, quand le gouvernement l''évalue à 884 milliards.', 'France Info', 'https://www.franceinfo.fr/economie/crise/crise-de-la-dette/cinq-questions-sur-la-proposition-de-jean-luc-melenchon-de-geler-une-partie-de-la-dette-francaise_8160833.html', '2026-08-27', '2026-09-09', 'annonce', null) on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-11'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:francois-ruffin'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:pouvoir-achat'), 'Porter le SMIC à 1 700 euros nets', 'Revaloriser le salaire minimum à 1 700 euros nets par mois.', 'Lors du lancement de sa campagne à Lyon, il annonce vouloir porter le SMIC à 1 700 € nets, avec une prime obligatoire de 1 000 € pour les salariés modestes et une indexation stricte des bas salaires sur l''inflation.', 'Orange Actu (dépêche AFP)', 'https://actu.orange.fr/france/presidentielle-2027-francois-ruffin-lance-sa-campagne-en-se-posant-en-defenseur-des-travailleurs-essentiels-magic-CNT000002oTqjw.html', '2026-04-26', '2026-09-09', 'annonce', 'SMIC, Salaire minimum') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-12'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:francois-ruffin'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:retraites'), 'Retraite anticipée pour les métiers pénibles', 'Propose un départ anticipé lié à la pénibilité du travail.', 'Lors de son meeting de lancement de campagne, il évoque une retraite anticipée liée à la pénibilité, une évolution par rapport à sa proposition antérieure d''un retour universel à 60 ans.', 'Orange Actu (dépêche AFP)', 'https://actu.orange.fr/france/presidentielle-2027-francois-ruffin-lance-sa-campagne-en-se-posant-en-defenseur-des-travailleurs-essentiels-magic-CNT000002oTqjw.html', '2026-04-26', '2026-09-09', 'annonce', 'Pénibilité, Départ anticipé') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-13'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:francois-ruffin'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:immigration'), 'Opposition à l''immigration de travail', 'Se déclare hostile à l''immigration de travail, notamment dans les services et la santé.', 'Il affirme ne pas vouloir « reproduire dans les services ce qui a été fait dans l''industrie », plaidant pour revaloriser les métiers afin d''attirer une main-d''œuvre locale plutôt que de recourir à des médecins étrangers.', 'Le Journal du Dimanche', 'https://www.lejdd.fr/politique/presidentielle-2027-francois-ruffin-se-dit-hostile-a-limmigration-de-travail-172605', '2026-04-28', '2026-09-09', 'annonce', 'Immigration de travail') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-14'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:francois-ruffin'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:ecologie'), 'Économie de guerre climatique et rénovation thermique massive', 'Appelle à une mobilisation économique massive pour la rénovation thermique des logements.', 'Défend une « économie de guerre climatique » inspirée du plan Roosevelt, avec un investissement public de 10 à 20 milliards d''euros par an pour éliminer les passoires thermiques.', 'Vert (média indépendant écologie)', 'https://vert.eco/articles/francois-ruffin-il-nous-faut-une-economie-de-guerre-climatique', '2023-06-09', '2026-09-09', 'programme', 'Rénovation thermique, Climat') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-15'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:francois-ruffin'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:energie'), 'Débat démocratique sur le nucléaire', 'Demande un débat démocratique sur le nucléaire sans direction imposée d''avance.', 'Il ne souhaite pas trancher unilatéralement la question du nucléaire mais veut un débat démocratique, tout en orientant la recherche publique vers les énergies renouvelables.', 'Vert (média indépendant écologie)', 'https://vert.eco/articles/francois-ruffin-il-nous-faut-une-economie-de-guerre-climatique', '2023-06-09', '2026-09-09', 'precision_ulterieure', 'Nucléaire') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-16'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:francois-ruffin'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:europe'), 'Défense européenne par coopération volontaire et « CECA du numérique »', 'Plaide pour une défense construite entre nations volontaires plutôt que pilotée par la Commission.', 'Critique l''approche supranationale de Bruxelles, propose une « CECA du numérique » pour réduire la dépendance aux GAFAM, et un plan de quotas pour 100 produits jugés essentiels à la souveraineté.', 'Le Grand Continent', 'https://legrandcontinent.eu/fr/2026/02/25/pour-une-declaration-dindependance-la-doctrine-ruffin-sur-leurope/', '2026-02-25', '2026-09-09', 'programme', 'Défense européenne, Souveraineté numérique') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-17'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:francois-ruffin'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:pouvoir-achat'), 'Créer un statut des travailleuses et travailleurs essentiels', 'Propose un statut dédié aux métiers essentiels à bas salaire, avec revalorisation, indexation sur l''inflation et meilleures conditions de travail.', 'Sur le site officiel de sa campagne, il détaille un statut pour environ 7 millions de travailleurs essentiels (aides à domicile, agents d''entretien, etc.) : indexation des salaires sur l''inflation, revalorisation des grilles pour 1,4 million de salariés à bas revenus, rémunération doublée pour les horaires avant 8h ou après 18h, fin des temps partiels subis avec un plancher de 24h/semaine, et trimestres de retraite anticipée bonifiés pour les métiers pénibles.', 'Site officiel de campagne de François Ruffin (Nous Président !)', 'https://nouspresident.fr/statut-travailleurs-essentiels/', '2026-08-30', '2026-09-09', 'proposition_officielle', null) on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-18'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-tondelier'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:pouvoir-achat'), 'Porter le SMIC à 2 000 euros brut', 'Défend une revalorisation du SMIC à 2 000 euros brut.', 'Lors du premier débat de la présidentielle 2027 fin août 2026, elle affirme que « le revenu pour les Français, c''est leur pouvoir d''achat » et non un coût pour les entreprises.', 'France 24', 'https://www.france24.com/fr/france/20260827-premier-d%C3%A9bat-de-la-pr%C3%A9sidentielle-2027-les-principales-propositions-des-candidats', '2026-08-27', '2026-09-09', 'annonce', 'SMIC') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-19'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-tondelier'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:retraites'), 'Opposition à l''âge légal de départ à 64 ans', 'S''oppose à la réforme portant l''âge légal de départ de 62 à 64 ans.', 'En tant que secrétaire nationale des Écologistes, elle a jugé nécessaire une mobilisation contre la réforme, en insistant sur ses impacts genrés.', 'Public Sénat', 'https://www.publicsenat.fr/actualites/politique/mobilisation-contre-la-reforme-des-retraites-pour-marine-tondelier-eelv-une', '2023-02-16', '2026-09-09', 'annonce', 'Âge légal') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-20'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-tondelier'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:immigration'), 'Pas de lien de causalité entre immigration et délinquance', 'Réfute tout lien de causalité direct entre immigration et délinquance.', 'Face à Marion Maréchal, elle affirme qu''il existe « un lien de causalité entre précarité et délinquance », les personnes immigrées étant statistiquement plus précaires.', 'Le Journal du Dimanche', 'https://www.lejdd.fr/politique/pas-de-lien-entre-immigration-et-delinquance-vif-echange-entre-marine-tondelier-et-marion-marechal-165165', '2025-12-19', '2026-09-09', 'precision_ulterieure', 'Débat public') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-21'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-tondelier'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:logement'), 'Encadrement renforcé des loyers des passoires énergétiques', 'Réclame un encadrement strict, avec des loyers 30 % moins chers, pour les passoires énergétiques relouées.', 'Face à la réautorisation de la location de logements énergivores, elle plaide pour des loyers « très encadrés » et réduits de 30 %, pour compenser l''exposition aux fortes chaleurs et les factures d''énergie supplémentaires.', 'AFP via Connaissance des Énergies', 'https://www.connaissancedesenergies.org/afp/location-de-passoires-energetiques-marine-tondelier-plaide-pour-des-loyers-30-moins-chers-260426', '2026-04-27', '2026-09-09', 'annonce', 'Loyers, Rénovation énergétique') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-22'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-tondelier'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:international'), 'Soutien à l''Ukraine et méfiance envers la Russie', 'Soutient un cessez-le-feu en Ukraine assorti de garanties de sécurité fortes.', 'Elle affirme qu''« on ne peut pas faire confiance à Poutine » et appelle à des garanties de sécurité fortes pour l''Ukraine, évoquant un déploiement de troupes au sol pour sécuriser les frontières.', 'franceinfo', 'https://www.franceinfo.fr/politique/guerre-en-ukraine-on-ne-peut-pas-faire-confiance-a-poutine-estime-marine-tondelier_7125150.html', '2025-03-12', '2026-09-09', 'precision_ulterieure', 'Ukraine, Défense') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-23'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-tondelier'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:economie'), 'Créer un ISF climatique et une TVA verte', 'Les Écologistes proposent un nouvel impôt sur la fortune modulé selon l''impact environnemental des patrimoines, une TVA verte, et une fiscalité renchérissant l''avion au profit du train.', 'Présenté le 13 juillet 2026, le programme de Marine Tondelier pour 2027 inclut la création d''un « ISF climatique » modulant la taxation selon l''impact environnemental des actifs, d''une « TVA verte », ainsi qu''une réforme de la fiscalité des transports visant à renchérir le coût du transport aérien tout en favorisant le ferroviaire.', 'Entrevue', 'https://entrevue.fr/elections/marine-tondelier-presente-le-programme-des-ecologistes-pour-2027/', '2026-07-13', '2026-09-09', 'programme', null) on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-24'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-tondelier'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:ecologie'), 'Taxer les grands héritages pour financer la transition écologique', 'Créer une surtaxe sur les héritages de plus de 4 millions d''euros pour financer l''adaptation au changement climatique.', 'Le programme des Écologistes prévoit une contribution de 10 % sur la part des héritages dépassant 4 millions d''euros, avec 10 points supplémentaires au-delà de 13 millions, ainsi qu''un abaissement de l''exonération du pacte Dutreil de 75 % à 50 % ; les recettes financeraient notamment un plan de rénovation des bâtiments scolaires (4 milliards d''euros par an sur dix ans), la restauration du fonds vert (+1,9 milliard) et la hausse de MaPrimeRénov'' (+1,4 milliard).', 'AFP via France 24', 'https://www.france24.com/fr/info-en-continu/20260826-les-ecologistes-veulent-taxer-davantage-les-h%C3%A9ritages-des-plus-fortun%C3%A9s-pour-financer-la-transition-%C3%A9cologique', '2026-08-26', '2026-09-09', 'proposition_officielle', 'Héritages, Transition écologique') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-25'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:raphael-glucksmann'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:pouvoir-achat'), 'Hausse du salaire net financée par la taxation des héritages', 'Baisser les prélèvements sociaux sur les salaires, financée par une taxe sur les très gros héritages.', 'Vise à récupérer environ 15 milliards d''euros en taxant les « méga-héritages » et le 1 % le plus riche, reversés sous forme de baisse de charges sur les salaires nets.', 'Public Sénat', 'https://www.publicsenat.fr/actualites/politique/fiscalite-ecole-immigration-ce-que-propose-raphael-glucksmann', '2026-08-24', '2026-09-09', 'proposition_officielle', 'Salaires, Fiscalité') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-26'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:raphael-glucksmann'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:retraites'), 'Réforme des retraites selon l''espérance de vie en bonne santé', 'Abroger la réforme de 2023 et moduler l''âge de départ selon la pénibilité et l''espérance de vie en bonne santé.', 'Départ plus précoce pour les carrières hachées et les métiers pénibles, départ plus tardif pour les cadres à espérance de vie plus longue, sans retour universel à 60 ans.', 'Public Sénat', 'https://www.publicsenat.fr/actualites/politique/fiscalite-ecole-immigration-ce-que-propose-raphael-glucksmann', '2026-08-24', '2026-09-09', 'proposition_officielle', 'Pénibilité, Âge légal') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-27'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:raphael-glucksmann'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:immigration'), 'Convention citoyenne sur l''immigration', 'Organiser une convention citoyenne tirée au sort pour débattre de la politique migratoire.', 'Il affirme vouloir assumer le débat migratoire en confrontant des citoyens tirés au sort aux données démographiques, économiques et sécuritaires, tout en rejetant une « immigration zéro ».', 'Public Sénat', 'https://www.publicsenat.fr/actualites/politique/fiscalite-ecole-immigration-ce-que-propose-raphael-glucksmann', '2026-08-24', '2026-09-09', 'proposition_officielle', 'Débat public') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-28'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:raphael-glucksmann'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:education'), 'Plan quinquennal de sauvetage de l''école publique', 'Plan sur cinq ans combinant hausse des salaires enseignants, baisse des effectifs et rénovation des bâtiments.', 'Priorité à la hausse de la rémunération des enseignants, puis baisse du nombre d''élèves par classe en primaire et rénovation du bâti scolaire, avec relance des colonies de vacances.', 'Public Sénat', 'https://www.publicsenat.fr/actualites/politique/fiscalite-ecole-immigration-ce-que-propose-raphael-glucksmann', '2026-08-24', '2026-09-09', 'proposition_officielle', 'Enseignants, Effectifs') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-29'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:raphael-glucksmann'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:international'), 'Emprunt européen de 500 milliards d''euros pour la défense', 'Propose un grand emprunt collectif européen pour financer une armée européenne unifiée.', 'Défend un mécanisme de solidarité européenne pour lever cette somme, dans le cadre de son plaidoyer pour une souveraineté militaire européenne face à la guerre en Ukraine.', 'Le Journal du Dimanche', 'https://www.lejdd.fr/politique/soutien-a-lukraine-glucksmann-suggere-un-grand-emprunt-collectif-europeen-de-500-milliards-deuros-155829', '2025-03-10', '2026-09-09', 'precision_ulterieure', 'Défense européenne') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-30'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:raphael-glucksmann'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:europe'), 'Suppression du droit de veto au Conseil européen', 'Propose de supprimer le droit de veto national dans certaines décisions de l''UE.', 'S''inscrit dans un plan de souveraineté européenne incluant un grand emprunt européen, présenté dans son projet présidentiel pour 2027.', 'LCP - Assemblée nationale', 'https://lcp.fr/actualites/presidentielle-raphael-glucksmann-devoile-les-premieres-lignes-de-son-possible-programme', '2026-08-15', '2026-09-09', 'proposition_officielle', 'Institutions européennes') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-31'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:raphael-glucksmann'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:economie'), 'Service civique obligatoire de dix mois pour les jeunes', 'Chaque jeune consacrerait dix mois à un service civique, avec une option militaire sur base volontaire.', 'Un « passeport pour l''émancipation » est aussi envisagé pour financer colonies de vacances et séjours collectifs pour chaque enfant.', 'Public Sénat', 'https://www.publicsenat.fr/actualites/politique/fiscalite-ecole-immigration-ce-que-propose-raphael-glucksmann', '2026-08-24', '2026-09-09', 'proposition_officielle', 'Service civique') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-32'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:raphael-glucksmann'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:education'), 'Relancer les colonies de vacances pour tous les enfants', 'Veut garantir à chaque enfant un séjour collectif en relançant les colonies de vacances.', 'Dans le cadre de son plan pour la jeunesse présenté fin août 2026, il propose de relancer les colonies de vacances en garantissant « à chaque enfant un séjour collectif », en complément de son plan quinquennal pour l''école publique.', 'Public Sénat', 'https://www.publicsenat.fr/actualites/politique/fiscalite-ecole-immigration-ce-que-propose-raphael-glucksmann', '2026-08-24', '2026-09-09', 'proposition_officielle', null) on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-33'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:gabriel-attal'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:economie'), 'Retour à l''équilibre budgétaire en dix ans', 'Plan d''économies de 120 à 150 milliards d''euros pour ramener le déficit à 3 % avant 2032 et à zéro en 2037.', 'Suppression de 100 000 postes de fonctionnaires par départs volontaires, une « année blanche » sur les prestations sociales en 2028, et un référendum pour une règle d''or budgétaire, en préservant Éducation, Armées, Justice et Intérieur.', 'Le JDD', 'https://www.lejdd.fr/politique/presidentielle-le-plan-de-gabriel-attal-pour-redresser-les-finances-publiques-177987', '2026-07-02', '2026-09-09', 'proposition_officielle', 'Budget, Fonction publique') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-34'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:gabriel-attal'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:retraites'), 'Suppression de l''âge légal, capitalisation en complément', 'Remplacer l''âge légal par la seule durée de cotisation et introduire une capitalisation.', 'Abolir l''âge fixe de départ au profit de la durée de cotisation avec mécanismes de décote/surcote, et ajouter un pilier de capitalisation (assurance-vie, PER).', 'Meilleurtaux Placement', 'https://placement.meilleurtaux.com/retraite/actualites/2026-mai/plan-de-gabriel-attal-retraites-supprimer-age-legal-instaurer-place-modele-hybride.html', '2026-05-07', '2026-09-09', 'proposition_officielle', 'Âge légal, Capitalisation') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-35'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:gabriel-attal'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:immigration'), 'Quotas migratoires par métier et origine géographique', 'Le Parlement voterait tous les deux ans des quotas d''immigration selon le métier, le secteur et l''origine géographique.', 'Sous le slogan « accueillir moins pour accueillir mieux », il priorise l''immigration de travail au détriment de l''immigration familiale et étudiante, tout en excluant une immigration zéro.', 'Le JDD', 'https://www.lejdd.fr/politique/immigration-gabriel-attal-propose-des-quotas-par-metier-et-par-origine-geographique-180879', '2026-08-10', '2026-09-09', 'proposition_officielle', 'Quotas') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-36'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:gabriel-attal'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:education'), 'Rétablir le certificat d''études et réduire la taille des classes', 'Restaurer un certificat d''études à l''entrée en 6e et limiter les classes de primaire à moins de 20 élèves.', 'Loi de programmation avec un ministre de l''Éducation en poste cinq ans, revalorisation salariale (200 à 500 € nets/mois), généralisation des groupes de niveau, fermeture des « 100 pires ghettos scolaires ».', 'LCP - Assemblée nationale', 'https://lcp.fr/actualites/presidentielle-retour-du-certificat-d-etudes-revalorisation-des-salaires-ce-que-propose', '2026-08-25', '2026-09-09', 'proposition_officielle', 'Effectifs, Enseignants') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-37'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:gabriel-attal'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:energie'), 'Produire les trois quarts de l''énergie française sur le territoire', 'Défend une souveraineté énergétique reposant sur un mix nucléaire-renouvelable.', 'Objectif affiché que 75 % de l''énergie consommée en France soit produite sur le territoire, en combinant relance du nucléaire et développement des renouvelables.', 'Presse Agence', 'https://presseagence.fr/strasbourg-gabriel-attal-une-nouvelle-donne-economique-et-climatique-pour-la-france/', '2026-05-18', '2026-09-09', 'annonce', 'Nucléaire, Renouvelables') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-38'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:gabriel-attal'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:ecologie'), '« Écologie du contrat » et maintien des ZFE', 'Propose une méthode de négociation avec les acteurs économiques tout en maintenant les zones à faibles émissions.', 'Ce volet du projet présenté à Strasbourg vise une transition écologique jugée équitable, combinant maintien des ZFE et mesures sociales d''accompagnement pour les ménages modestes.', 'Presse Agence', 'https://presseagence.fr/strasbourg-gabriel-attal-une-nouvelle-donne-economique-et-climatique-pour-la-france/', '2026-05-18', '2026-09-09', 'annonce', 'ZFE, Transition') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-39'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:gabriel-attal'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:sante'), 'Référendum pour interdire les réseaux sociaux aux moins de 15 ans', 'Demande un référendum interdisant les réseaux sociaux aux mineurs de moins de 15 ans.', 'Invoquant la protection de la santé mentale des enfants, il évoque 1,5 million d''enfants quotidiennement exposés aux algorithmes pendant près de deux heures.', 'franceinfo', 'https://www.franceinfo.fr/internet/reseaux-sociaux/une-course-contre-la-montre-a-demarre-gabriel-attal-appelle-a-un-referendum-sur-l-interdiction-des-reseaux-aux-moins-de-15-ans_8149565.html', '2026-08-16', '2026-09-09', 'annonce', 'Santé mentale, Numérique') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-40'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:gabriel-attal'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:europe'), 'Faire de la France « la première puissance d''Europe »', 'Ambition affichée de faire redevenir la France la première puissance d''Europe.', 'Formulée le 22 mai 2026 à Mur-de-Barrez (Aveyron), lors du déplacement au cours duquel il a officialisé sa candidature à l''élection présidentielle de 2027.', 'franceinfo', 'https://www.franceinfo.fr/elections/presidentielle/j-aime-passionnement-la-france-et-j-aime-profondement-les-francais-gabriel-attal-se-declare-candidat-a-l-election-presidentielle-de-2027_8020769.html', '2026-05-22', '2026-09-09', 'annonce', 'Souveraineté') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-41'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:gabriel-attal'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:economie'), 'Plan France 2040 de 200 milliards d''euros pour l''IA', 'Veut faire de la France la première puissance européenne en intelligence artificielle grâce à un plan de 200 milliards d''euros sur dix ans.', 'Dans un entretien aux Échos publié le 17 juin 2026, il détaille un « plan France 2040 » pour l''intelligence artificielle et l''innovation doté de 200 milliards d''euros (moitié publics, moitié privés), avec un crédit d''impôt productivité pour l''adoption de l''IA dans les PME/ETI et un objectif de former 20 millions de salariés d''ici 2030.', 'Les Échos', 'https://www.lesechos.fr/elections/presidentielle/gabriel-attal-il-faut-lequivalent-de-la-politique-agricole-commune-pour-lia-2237679', '2026-06-17', '2026-09-09', 'proposition_officielle', null) on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-42'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:gabriel-attal'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:pouvoir-achat'), 'Réduire les cotisations salariales pour rapprocher net et brut', 'Propose de baisser les cotisations salariales afin d''augmenter le salaire net à salaire brut égal.', 'Dans le même entretien aux Échos du 17 juin 2026, il propose une réduction des cotisations salariales pour rapprocher le salaire net du salaire brut, avec un engagement de stabilité tarifaire de l''électricité sur cinq ans pour les entreprises.', 'Les Échos', 'https://www.lesechos.fr/elections/presidentielle/gabriel-attal-il-faut-lequivalent-de-la-politique-agricole-commune-pour-lia-2237679', '2026-06-17', '2026-09-09', 'annonce', null) on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-43'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:edouard-philippe'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:education'), 'Hausse de 20 % de la rémunération des enseignants', 'Augmenter la rémunération moyenne des enseignants de 20 % sur un quinquennat.', 'Porter les salaires au moins au niveau de la moyenne européenne, en particulier en milieu de carrière, en s''appuyant sur la baisse démographique du nombre d''élèves pour financer la mesure.', 'franceinfo', 'https://www.franceinfo.fr/elections/presidentielle/presidentielle-2027-le-candidat-horizons-edouard-philippe-veut-augmenter-de-20-la-remuneration-moyenne-des-enseignants-sur-un-quinquennat_8159927.html', '2026-08-24', '2026-09-09', 'proposition_officielle', 'Enseignants, Salaires') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-44'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:edouard-philippe'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:education'), 'L''école, priorité du premier meeting de campagne', 'Fait de l''école la « boussole » du prochain quinquennat lors de son premier grand meeting.', 'Il annonce vouloir donner aux chefs d''établissement « les moyens d''être des patrons », revaloriser les enseignants, repenser le rythme scolaire et intégrer l''intelligence artificielle dans l''enseignement.', 'TIME France', 'https://www.timefrance.fr/politique/presidentielle-2027-edouard-philippe-entre-en-campagne-et-place-lecole-au-coeur-de-ses-priorites/', '2026-07-06', '2026-09-09', 'annonce', 'Enseignants, Réforme scolaire') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-45'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:edouard-philippe'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:retraites'), 'Relever l''âge légal de départ au-delà de 64 ans', 'Défend un nouveau relèvement de l''âge légal de départ à la retraite, potentiellement à 65, 66 ou 67 ans.', 'N''ayant pu mener à bien sa réforme systémique par points en 2020, il plaide pour poursuivre le relèvement de l''âge légal au-delà des 64 ans issus de la réforme de 2023.', 'Boursorama / APMnews', 'https://www.boursorama.com/epargne/retraite/actualites/reforme-des-retraites-les-propositions-d-edouard-philippe-aux-partenaires-sociaux-696742779bab5b90918b3b69dc9b1a02', '2026-01-01', '2026-09-09', 'precision_ulterieure', 'Âge légal') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-46'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:edouard-philippe'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:immigration'), 'Instauration de quotas d''immigration professionnelle', 'Défend la mise en place d''objectifs quantitatifs pour l''immigration de travail.', 'Propose des quotas annuels d''immigration soumis à un vote du Parlement, une priorité donnée à l''immigration de travail dans les secteurs en tension, et un durcissement du regroupement familial.', 'Europe1', 'https://www.europe1.fr/politique/immigration-edouard-philippe-confirme-linstauration-dobjectifs-qualitatifs-ou-de-quotas-3929658', '2024-01-01', '2026-09-09', 'proposition_officielle', 'Quotas, Immigration de travail') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-47'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:edouard-philippe'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:energie'), 'Mix énergétique fondé sur le nucléaire et les renouvelables', 'Promet davantage de nucléaire et davantage de renouvelables, sans opposer les deux filières.', 'Il présente le nucléaire comme « la seule énergie abondante, aux coûts prévisibles, économe en espace et ne produisant pas de CO2 », tout en voulant développer les renouvelables.', 'Compte X officiel @EPhilippe_LH', 'https://x.com/EPhilippe_LH/status/2044857410607583437', '2026-04-01', '2026-09-09', 'annonce', 'Nucléaire, Renouvelables') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-48'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:edouard-philippe'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:logement'), 'Renforcer les droits des propriétaires et alléger les normes', 'Propose de renforcer le droit des propriétaires et de suspendre temporairement certaines obligations de rénovation énergétique.', 'Devant le congrès de la Fnaim, il s''est prononcé contre l''encadrement des loyers, pour une réforme de l''IFI jugé dissuasif, et pour une suspension temporaire des obligations de rénovation de la loi Climat et Résilience.', 'Immo Matin', 'https://www.immomatin.com/franchise/reseaux-franchise/renforcer-le-droit-du-proprietaire-pour-fluidifier-le-marche-edouard-philippe-congres-fnaim-2025.html', '2025-12-10', '2026-09-09', 'proposition_officielle', 'Propriétaires, Rénovation énergétique') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-49'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:edouard-philippe'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:education'), 'Créer une amende de responsabilisation scolaire pour les parents', 'Veut sanctionner financièrement les parents d''élèves harceleurs, perturbateurs ou violents, sur le modèle britannique.', 'Le 24 août 2026, il a proposé une « amende de responsabilisation scolaire », inspirée du Royaume-Uni, permettant au maire, sur proposition de l''équipe pédagogique, de sanctionner rapidement les parents d''élèves harceleurs, perturbateurs, absentéistes ou violents.', 'LCP - Assemblée nationale', 'https://lcp.fr/actualites/presidentielle-salaires-des-enseignants-sanctions-pour-les-parents-ce-que-propose', '2026-08-24', '2026-09-09', 'proposition_officielle', null) on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-50'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:edouard-philippe'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:securite'), 'Peines minimales et suppression du juge d''application des peines', 'Veut instaurer des peines minimales pour les infractions les plus graves et supprimer le juge de l''application des peines.', 'Il a détaillé, autour de plusieurs mesures pour « une France plus sûre », l''instauration de peines minimales pour les infractions les plus graves et la suppression du juge de l''application des peines, dans le cadre de son axe consacré au rétablissement de l''autorité et de la fermeté judiciaire.', 'CNEWS', 'https://www.cnews.fr/france/2026-07-19/presidentielle-2027-edouard-philippe-defend-une-france-plus-sure-et-met-laccent', '2026-07-19', '2026-09-09', 'proposition_officielle', null) on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-51'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:bruno-retailleau'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:immigration'), 'Référendum constitutionnel élargi à l''immigration', 'Propose une révision constitutionnelle permettant de soumettre au référendum des textes sur l''immigration.', 'Souhaite modifier l''article 11 de la Constitution et soumettre à référendum dès l''automne 2027 une « charte de l''ordre républicain » ; propose aussi d''abaisser de 5 à 2,5 millions le seuil de signatures pour un référendum d''initiative partagée.', 'Epoch Times', 'https://www.epochtimes.fr/presidentielle-bruno-retailleau-veut-donner-le-dernier-mot-aux-francais-par-referendum-3339141.html', '2026-09-03', '2026-09-09', 'proposition_officielle', 'Référendum, Constitution') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-52'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:bruno-retailleau'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:securite'), 'Plan de lutte contre le crime organisé et le narcotrafic', 'Dispositif renforcé contre la criminalité organisée et le trafic de drogue, présenté comme ministre de l''Intérieur.', 'Cellule nationale de coordination au parquet de Paris, renforcement des effectifs à Marseille, magistrat de liaison à Bogota, saisie administrative des avoirs et expulsion des trafiquants de leur logement.', 'France Info', 'https://www.franceinfo.fr/societe/drogue/direct-lutte-contre-le-narcotrafic-les-ministres-bruno-retailleau-et-didier-migaud-a-marseille-pour-annoncer-des-mesures_6884903.html', '2024-11-08', '2026-09-09', 'annonce', 'Narcotrafic, Police') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-53'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:bruno-retailleau'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:economie'), '120 milliards d''euros d''économies budgétaires d''ici 2032', 'S''engage sur un plan d''économies de 120 milliards d''euros de dépenses publiques d''ici 2032.', 'Présente cette trajectoire comme un « prérequis de crédibilité budgétaire » préalable à toute baisse d''impôts, en se disant ouvert à étudier une piste de type « flat tax ».', 'Contrepoints', 'https://contrepoints.org/flat-tax-aides-aux-entreprises-assurances-sociales-calendrier-des-reformes-bruno-retailleau-repond-a-nos-questions/', '2026-04-15', '2026-09-09', 'precision_ulterieure', 'Budget') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-54'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:bruno-retailleau'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:pouvoir-achat'), 'Plan « Travail gagnant » et revenu d''incitation à l''activité', 'Propose d''annualiser le temps de travail au-delà de 1 623 heures sans charges sociales et de remplacer le RSA par un revenu conditionné à une activité.', 'Les heures travaillées au-delà de 1 623 heures annuelles seraient exonérées de cotisations ; un « revenu d''incitation à l''activité » fusionnerait RSA, prime d''activité et allocation de solidarité, avec un plafond des aides sociales à 70 % du SMIC.', 'Yahoo Finance France', 'https://fr.finance.yahoo.com/actualites/travail-gagnant-propositions-chocs-bruno-182132757.html', '2026-01-07', '2026-09-09', 'proposition_officielle', 'Aides sociales, Travail') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-55'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:bruno-retailleau'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:retraites'), 'Indexation de l''âge de départ sur l''espérance de vie', 'Propose de lier progressivement l''âge de départ à la retraite à l''évolution de l''espérance de vie.', 'Il affirme que cette indexation garantirait l''équilibre financier du système sans avoir à rouvrir régulièrement le débat par une nouvelle réforme.', 'France Info', 'https://www.franceinfo.fr/elections/presidentielle/dette-publique-retraites-reindustrialisation-ce-qu-il-faut-retenir-du-premier-debat-des-principaux-candidats-a-la-presidentielle_8165342.html', '2026-08-27', '2026-09-09', 'annonce', 'Âge légal') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-56'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:bruno-retailleau'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:education'), 'Refonder l''école autour de quatre axes', 'Plan structuré autour des enseignants, de la transmission des savoirs, de la liberté des établissements et de l''autorité.', 'Revalorisation salariale des enseignants, retour à un enseignement fondé sur la transmission, autonomie accrue avec 1 000 écoles publiques « libres », et renforcement des pouvoirs disciplinaires des chefs d''établissement.', 'Public Sénat', 'https://www.publicsenat.fr/actualites/politique/presidentielle-2027-bruno-retailleau-veut-refonder-lecole-autour-de-quatre-axes-principaux', '2026-08-31', '2026-09-09', 'programme', 'Enseignants, Autonomie') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-57'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:bruno-retailleau'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:ecologie'), 'Une « écologie de l''adaptation » plutôt que punitive', 'Oppose à une écologie jugée « punitive » une écologie fondée sur l''adaptation et l''innovation.', 'Met en avant le stockage de l''eau, le recours au nucléaire et à la géothermie, l''adaptation des normes de construction et une révision du principe de précaution face aux vagues de chaleur.', 'Les Républicains (site officiel)', 'https://republicains.fr/actualites/2026/08/09/face-au-rechauffement-climatique-adapter-la-france-plutot-que-punir/', '2026-08-09', '2026-09-09', 'proposition_officielle', 'Adaptation climatique') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-58'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:bruno-retailleau'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:energie'), 'Fin des subventions à l''éolien et au photovoltaïque', 'Appelle à arrêter le financement public de l''éolien et du photovoltaïque et à reconstruire un parc nucléaire.', 'Avec deux vice-présidents de LR, il estime que l''intermittence de ces énergies fait courir un risque de « black-out » et pèse sur le pouvoir d''achat via les coûts de raccordement.', 'Public Sénat', 'https://www.publicsenat.fr/actualites/politique/fin-des-subventions-aux-eoliennes-et-au-photovoltaique-la-tribune-de-bruno-retailleau-met-le-socle-commun-en-surchauffe', '2025-07-03', '2026-09-09', 'precision_ulterieure', 'Renouvelables, Nucléaire') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-59'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:bruno-retailleau'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:europe'), 'Réserver l''espace Schengen aux ressortissants européens', 'Demande une refonte de Schengen pour réserver la libre circulation aux ressortissants européens.', 'Propose de généraliser les visas à validité territoriale limitée, de déployer Frontex à Ceuta, et critique la régularisation par l''Espagne de centaines de milliers de personnes.', 'Les Républicains (site officiel)', 'https://republicains.fr/actualites/2026/08/02/lespace-schengen-doit-etre-reserve-aux-europeens/', '2026-08-02', '2026-09-09', 'proposition_officielle', 'Schengen, Frontières') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-60'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:bruno-retailleau'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:logement'), 'Plan « Mieux se loger, et moins cher »', 'Vise un million de logements supplémentaires en cinq ans par un choc d''offre.', 'Suppression du dispositif ZAN, loi d''urgence pour ramener les délais de construction de 7 à 3 ans, fin de l''encadrement des loyers et des interdictions liées au DPE, reversement de 9 000 € de TVA aux communes par logement neuf construit.', 'Journal de l''Agence', 'https://www.journaldelagence.com/1411841-presidentielle-2027-les-propositions-de-bruno-retailleau-pour-relancer-le-logement', '2026-06-10', '2026-09-09', 'programme', 'Construction, Loyers') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-61'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:bruno-retailleau'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:economie'), 'Réduire le nombre de fonctionnaires de 250 000 à 300 000', 'Propose une diminution du nombre de fonctionnaires comprise entre 250 000 et 300 000 postes.', 'Lors du débat économique organisé par le Medef le 27 août 2026, il a proposé une diminution du nombre de fonctionnaires « autour de 250-300 000 », et a suggéré de lier l''âge de départ à la retraite à l''espérance de vie.', 'France Info', 'https://www.franceinfo.fr/elections/presidentielle/reportage-vous-n-etes-pas-obligee-de-raconter-n-importe-quoi-a-roland-garros-un-premier-debat-offensif-sur-l-economie-entre-les-sept-principaux-candidats-a-la-presidentielle_8164652.html', '2026-08-28', '2026-09-09', 'annonce', null) on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-62'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:bruno-retailleau'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:education'), 'Créer des internats disciplinaires pour élèves violents', 'Veut créer des internats disciplinaires destinés aux élèves violents ou harceleurs récidivistes.', 'Le 1er septembre 2026, jour de la rentrée scolaire, il a dévoilé sa première mesure pour l''école : la création d''« internats disciplinaires » gérés par du personnel volontaire et expérimenté, destinés aux élèves violents ou harceleurs récidivistes séparés de familles « défaillantes », dans le cadre de sa volonté de restaurer l''autorité à l''école.', 'Orange Actu (6Médias avec L''Express)', 'https://actu.orange.fr/france/des-internats-disciplinaires-bruno-retailleau-devoile-sa-premiere-mesure-pour-l-ecole-en-cas-d-election-magic-CNT000002rE9Rv.html', '2026-09-01', '2026-09-09', 'proposition_officielle', null) on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-63'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:bruno-retailleau'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:immigration'), 'Supprimer le droit du sol par référendum', 'Veut abroger le droit du sol et soumettre une loi de réduction de l''immigration au référendum.', 'Sur CNews et Europe 1, il affirme vouloir réviser la Constitution pour élargir le champ du référendum et y soumettre « une loi pour réduire l''immigration » abolissant le droit du sol, jugeant qu''on « ne peut pas devenir français par hasard, en catimini, de façon automatique », et citant en exemple sa suppression déjà mise en œuvre à Mayotte.', 'Orange Actu (AFP)', 'https://actu.orange.fr/politique/retailleau-veut-supprimer-le-droit-du-sol-par-referendum-CNT000002rNmsn.html', '2026-09-09', '2026-09-09', 'annonce', 'Droit du sol, Référendum') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-64'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:xavier-bertrand'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:securite'), 'Peine de prison automatique contre les agressions d''agents publics', 'Veut rendre automatique la peine de prison pour toute agression visant un policier, un gendarme, un pompier ou un maire.', 'Propose une révision constitutionnelle pour instaurer cette automaticité, dans le contexte du « Beauvau de la sécurité ».', 'Les Surligneurs', 'https://www.lessurligneurs.eu/pour-xavier-bertrand-lr-si-on-sen-prend-a-un-policier-a-un-gendarme-a-un-pompier-ou-un-maire-la-peine-de-prison-doit-etre-automatique/', '2021-04-18', '2026-09-09', 'proposition_officielle', 'Justice, Sanctions') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-65'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:xavier-bertrand'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:securite'), '« Révolution pénale » : prisons, peines plancher, majorité pénale', 'Plan pénal comprenant 20 000 places de prison supplémentaires, des peines plancher et l''abaissement de la majorité pénale à 15 ans.', 'En réponse au « Beauvau de la sécurité », il détaille sa « révolution pénale », incluant la création d''officiers de police judiciaire territoriaux au sein des polices municipales.', 'Public Sénat', 'https://www.publicsenat.fr/actualites/politique/apres-le-beauvau-de-la-securite-xavier-bertrand-repond-a-emmanuel-macron-en', '2021-09-15', '2026-09-09', 'programme', 'Prisons, Peines plancher') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-66'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:xavier-bertrand'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:immigration'), 'Référendum à trois questions sur immigration, sûreté et laïcité', 'Propose un référendum modifiant la Constitution sur l''immigration, la rétention de sûreté et la laïcité.', 'Il a proposé d''organiser un référendum posant trois questions distinctes pour réviser la Constitution — une formule qui, selon le Conseil constitutionnel, exigerait en réalité plusieurs référendums séparés.', 'Les Surligneurs', 'https://www.lessurligneurs.eu/xavier-bertrand-souhaite-un-referendum-a-trois-questions-pour-modifier-la-constitution-immigration-terrorisme-laicite/', '2020-12-06', '2026-09-09', 'proposition_officielle', 'Référendum, Constitution') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-67'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:xavier-bertrand'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:immigration'), '« Reprendre le contrôle » de l''immigration par des quotas votés', 'Propose des quotas migratoires annuels votés par le Parlement, la fin des régularisations et l''expulsion des étrangers condamnés.', 'Programme fondé sur une révision constitutionnelle par référendum pour que le Parlement fixe chaque année des quotas d''immigration, avec priorité réduite au regroupement familial.', 'Europe 1', 'https://www.europe1.fr/politique/xavier-bertrand-devoile-ses-propositions-pour-reprendre-le-controle-de-limmigration-4075260', '2021-11-04', '2026-09-09', 'programme', 'Quotas') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-68'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:xavier-bertrand'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:energie'), 'Maintien du nucléaire au-delà de 50 % du mix électrique', 'Refuse de réduire la part du nucléaire à 50 % et regrette la fermeture de la centrale de Fessenheim.', 'Se prononce pour le lancement de nouveaux réacteurs nucléaires et critique l''éolien comme réponse insuffisante aux besoins énergétiques.', 'France Info', 'https://www.franceinfo.fr/environnement/energie/video-energie-je-ne-descendrai-pas-la-part-du-nucleaire-a-50-assure-xavier-bertrand_4794405.html', '2021-10-04', '2026-09-09', 'proposition_officielle', 'Nucléaire') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-69'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:xavier-bertrand'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:economie'), 'Renforcer la taxation fiscale des géants du numérique (GAFA)', 'Juge la taxe GAFA du gouvernement insuffisante et veut taxer plus fortement ces entreprises.', 'Propose d''utiliser les recettes d''une taxation plus lourde des GAFA pour réduire les cotisations sociales et impôts des Français.', 'ICI (France 3)', 'https://www.ici.fr/infos/politique/xavier-bertrand-invite-de-dimanche-en-politique-1547295534', '2019-01-13', '2026-09-09', 'proposition_officielle', 'Fiscalité, Numérique') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-70'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:xavier-bertrand'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:logement'), 'Le logement comme priorité stratégique nationale', 'Appelle à faire du logement un axe stratégique de l''action publique, au même niveau que la santé, l''éducation ou la justice.', 'Invité des Assises nationales du Logement et de la Ville, il plaide pour une relance de la construction par la simplification des normes et une plus grande stabilité réglementaire.', 'Batiactu', 'https://www.batiactu.com/edito/assises-logement-2026-xavier-bertrand-appelle-a-faire-74799.php', '2026-06-23', '2026-09-09', 'proposition_officielle', 'Construction') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-71'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-le-pen'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:pouvoir-achat'), 'Baisse de la TVA à 5,5 % sur l''énergie', 'Réduire la TVA de 20 % à 5,5 % sur le gaz, le fioul, l''électricité et les carburants.', 'Défendue via un amendement au budget 2026, cette mesure vise un « choc de pouvoir d''achat » pour les ménages, ces produits étant qualifiés de biens de première nécessité.', 'CNEWS (amendement RN au budget 2026)', 'https://www.cnews.fr/france/2025-10-21/abaissement-de-la-tva-55-quels-produits-sont-concernes-par-lamendement-depose-par', '2025-10-21', '2026-09-09', 'proposition_officielle', 'TVA, Énergie') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-72'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-le-pen'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:retraites'), 'Retour à la retraite à 62 ans, 60 ans pour carrières longues', 'Maintient sa volonté d''abaisser l''âge légal de départ à la retraite à 62 ans, voire 60 ans pour les carrières longues.', 'Position réaffirmée sur RTL en mai 2026 comme « toujours d''actualité », cohérente avec ses programmes de 2022 et 2024, mais faisant débat en interne au RN dans la préparation du programme 2027.', 'Public Sénat', 'https://www.publicsenat.fr/actualites/politique/au-rn-la-reforme-des-retraites-divise-jordan-bardella-et-marine-le-pen-sur-le-programme-pour-la-presidentielle-2027', '2026-06-12', '2026-09-09', 'precision_ulterieure', 'Âge légal') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-73'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-le-pen'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:immigration'), 'Référendum « Citoyenneté-Identité-Immigration »', 'Propose de soumettre à référendum un projet de loi encadrant l''immigration.', 'Le projet « C2i » prévoit l''interdiction des régularisations, une priorité nationale pour le logement et l''emploi, l''expulsion des étrangers délinquants et la fin du regroupement familial.', 'Public Sénat', 'https://www.publicsenat.fr/actualites/politique/immigration-le-referendum-voulu-par-marine-le-pen-est-il-constitutionnel-190598', '2021-09-29', '2026-09-09', 'proposition_officielle', 'Référendum, Régularisation') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-74'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-le-pen'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:energie'), 'Moratoire sur la construction d''éoliennes', 'Veut un moratoire sur toute nouvelle construction d''éoliennes et leur démantèlement progressif, au profit du nucléaire.', 'Elle qualifie les éoliennes de « saccage environnemental » et défend le nucléaire, les énergies renouvelables n''étant selon elle « ni propres ni renouvelables ».', 'Déclaration sur BFM TV (via TucoEnergie)', 'https://www.tucoenergie.fr/blog/marine-le-pen-bfmtv', '2024-06-05', '2026-09-09', 'annonce', 'Éolien, Nucléaire') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-75'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-le-pen'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:sante'), 'Moratoire sur la fermeture de lits d''hôpitaux', 'Propose un moratoire sur la fermeture de lits dans les hôpitaux publics et des incitations pour installer des médecins en zones sous-dotées.', 'Propose un stage d''internat obligatoire en zone sous-dense, le développement de la télémédecine, et une enveloppe de 2 milliards d''euros sur cinq ans pour revaloriser les salaires des soignants.', 'Discours « Santé : protégeons les Français ! » (RN)', 'https://rassemblementnational.fr/discours/sante-protegeons-les-francais-discours-de-marine-le-pen', '2016-12-09', '2026-09-09', 'programme', 'Hôpital public') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-76'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-le-pen'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:economie'), 'Règle d''or budgétaire et 125 milliards d''économies', 'Propose d''inscrire une règle d''or budgétaire dans la Constitution et un plan de 125 milliards d''euros d''économies sur cinq ans.', 'Le 31 août 2026, elle a annoncé vouloir inscrire dans la Constitution une « règle d''or » limitant le déficit public à 3 % du PIB, ainsi qu''un plan de réduction des dépenses de fonctionnement de 125 milliards d''euros sur cinq ans, concentré sur les deux premières années.', 'LCP - Assemblée nationale', 'https://lcp.fr/actualites/une-regle-d-or-budgetaire-pourquoi-le-rn-abandonne-l-un-de-ses-marqueurs-historiques-sur', '2026-08-31', '2026-09-09', 'annonce', null) on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-77'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:david-lisnard'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:retraites'), 'Retraite à 65 ans et capitalisation obligatoire complémentaire', 'Porter l''âge légal à 65 ans et rendre obligatoire une capitalisation complémentaire à la répartition.', 'Le programme prévoit une pension minimale assurée par répartition, complétée par une capitalisation obligatoire sur le reste des cotisations, avec une transition en environ 8 tranches successives vers un encours de capitalisation de 116 milliards d''euros (environ 40 % du montant total des retraites) ; le minimum vieillesse serait porté à 1 000 euros mensuels.', 'Programme de campagne — Nouvelle Énergie', 'https://www.unenouvelleenergie.fr/notre-programme/reussir-une-nouvelle-ambition-francaise/', '2026-07-03', '2026-09-09', 'programme', 'Âge légal, Capitalisation') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-78'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:david-lisnard'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:immigration'), 'Diviser par huit les titres de séjour et durcir les conditions d''entrée', 'Réduire d''un facteur huit la délivrance de titres de séjour et durcir regroupement familial, droit du sol et rétention.', 'Le programme prévoit de revenir sur l''accord franco-algérien de 1968, de diviser par huit la délivrance de titres de séjour, de conditionner le regroupement familial à des critères de ressources et des tests d''intégration, de mettre fin à l''automaticité du droit du sol, d''allonger la rétention administrative à 24 mois, de supprimer l''Aide Médicale d''État (700 millions d''euros d''économies visées), de rétablir le délit de séjour irrégulier, et de conditionner les prestations sociales non contributives à 5 ans de résidence régulière.', 'Programme de campagne — Nouvelle Énergie', 'https://www.unenouvelleenergie.fr/notre-programme/immigration/', '2026-07-03', '2026-09-09', 'programme', 'Titres de séjour, Regroupement familial') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-79'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:david-lisnard'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:securite'), 'Armer les polices municipales et durcir la réponse pénale', 'Étendre les pouvoirs des polices municipales et durcir les peines, dont l''abaissement de la majorité pénale à 16 ans.', 'Le programme prévoit de ramener 50 % des forces de sécurité sur le terrain (contre 37 % actuellement), de permettre aux communes d''armer leur police municipale avec accès aux fichiers, de créer des cellules locales anti-stups sous autorité préfectorale, de supprimer les réductions de peine automatiques, de rétablir des peines plancher pour les récidivistes, de doubler les effectifs des juridictions correctionnelles, et d''abaisser la majorité pénale à 16 ans.', 'Programme de campagne — Nouvelle Énergie', 'https://www.unenouvelleenergie.fr/notre-programme/securite/', '2026-07-03', '2026-09-09', 'programme', 'Police municipale, Justice pénale') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-80'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:david-lisnard'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:economie'), 'Règle d''or budgétaire et dépense publique sous 50 % du PIB', 'Instaurer une règle d''or sur les dépenses de fonctionnement pour ramener la dépense publique sous 50 % du PIB en cinq ans.', 'S''appuyant sur l''exemple de la Suède et de l''Allemagne (une baisse de 8 points de PIB en 10 ans), le programme vise à réduire la dépense publique de 55,6 % à moins de 50 % du PIB sans attendre 2027, via une règle d''or appliquée au fonctionnement (pas à l''investissement), une réduction des tâches administratives de 33 % à 25 % (le taux allemand), et le redéploiement de 450 000 fonctionnaires des bureaux vers le terrain.', 'Programme de campagne — Nouvelle Énergie', 'https://www.unenouvelleenergie.fr/notre-programme/etre-maitre-de-notre-destin/', '2026-07-03', '2026-09-09', 'programme', 'Dépense publique, Fonction publique') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-81'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:david-lisnard'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:economie'), 'Baisse de moitié des impôts de production et contrat de travail unique', 'Supprimer la C3S et alléger la CVAE pour diviser par deux les impôts de production, et fusionner CDI et CDD.', 'La suppression de la C3S et, le cas échéant, de la CVAE représenterait 11,5 milliards d''euros d''allégement, combinés aux 10 milliards déjà prévus par le gouvernement, pour une diminution de moitié des impôts de production (de 2 % à 1 % du PIB). Le programme prévoit aussi un contrat de travail unique fusionnant CDI et CDD, la suppression des charges employeur au niveau du SMIC, et des charges patronales négatives pour l''embauche de bénéficiaires du RSA depuis plus de deux ans.', 'Programme de campagne — Nouvelle Énergie', 'https://www.unenouvelleenergie.fr/notre-programme/reussir-une-nouvelle-ambition-francaise/', '2026-07-03', '2026-09-09', 'programme', 'Fiscalité des entreprises, Emploi') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-82'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:david-lisnard'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:education'), 'Chèque-éducation, autonomie des établissements et +20 % pour les enseignants', 'Instaurer un chèque-éducation, donner l''autonomie de recrutement aux établissements et augmenter les enseignants de 20 % en cinq ans.', 'Le programme prévoit d''abroger la carte scolaire, d''instaurer progressivement un chèque-éducation (financement public équivalent que la famille choisisse le public ou le privé), de donner aux chefs d''établissement la liberté de recruter leurs équipes, d''appliquer leurs méthodes et de gérer leur budget, d''instaurer un certificat de fin de primaire conditionnant l''entrée au collège, d''étendre l''enseignement du grec, du latin et de la philosophie dès le primaire, et d''augmenter les rémunérations enseignantes de 20 % en cinq ans.', 'Programme de campagne — Nouvelle Énergie', 'https://www.unenouvelleenergie.fr/notre-programme/education/', '2026-07-03', '2026-09-09', 'programme', 'Autonomie, Enseignants') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-83'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:david-lisnard'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:sante'), 'Fin des ARS et doublement des étudiants en médecine d''ici 2030', 'Supprimer les Agences régionales de santé et doubler le nombre d''étudiants en médecine d''ici 2030.', 'Le programme prévoit un conventionnement différencié (mieux rembourser les actes en zones sous-dotées qu''en zones saturées), la généralisation de maisons de santé pluridisciplinaires à l''échelle de chaque canton, l''accès direct aux infirmiers, kinés et pharmaciens, la suppression des Agences régionales de santé au profit des préfets et des élus locaux (dont la présidence des conseils d''administration d''hôpitaux rendue aux maires), et le doublement du nombre d''étudiants en médecine d''ici 2030.', 'Programme de campagne — Nouvelle Énergie', 'https://www.unenouvelleenergie.fr/notre-programme/sante/', '2026-07-03', '2026-09-09', 'programme', 'Hôpital public, Accès aux soins') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-84'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:david-lisnard'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:energie'), 'Prolonger les réacteurs nucléaires à 60 ans et construire de nouveaux EPR', 'Faire du nucléaire une priorité stratégique, en prolongeant les réacteurs existants et en construisant de nouveaux EPR et mini-réacteurs.', 'Le programme présente le nucléaire comme une « priorité écologique et stratégique » pour la souveraineté industrielle : prolongation de la durée de vie des réacteurs jusqu''à 60 ans, construction d''EPR de nouvelle génération, déploiement de mini-réacteurs, complétés par une fiscalité carbone de type pollueur-payeur redistribuée aux ménages les plus affectés et neutre pour la compétitivité.', 'Programme de campagne — Nouvelle Énergie', 'https://www.unenouvelleenergie.fr/notre-programme/generer-un-renouveau-civique/', '2026-07-03', '2026-09-09', 'programme', 'Nucléaire, Fiscalité carbone') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-85'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:fabien-roussel'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:retraites'), 'Retour de l''âge légal de départ à 60 ans', 'Rétablir la retraite à 60 ans, financée par la taxation des revenus financiers et la lutte contre le chômage.', 'Le PCF propose de rétablir l''âge de départ à la retraite à 60 ans, en finançant la réforme par une taxation des revenus financiers et une baisse du chômage plutôt que par un allongement de la durée de cotisation.', 'Parti communiste français (pcf.fr)', 'https://www.pcf.fr/retraites_pour_une_r_forme_digne_des_jours_heureux', '2026-09-06', '2026-09-09', 'programme', 'Âge légal') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-86'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:fabien-roussel'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:pouvoir-achat'), 'SMIC à 1 500 euros net et semaine de 32 heures', 'Porter le SMIC à 1 500 euros net, instaurer la semaine de 32 heures sans perte de salaire et revaloriser les petites retraites à 1 200 euros net.', 'Ce socle social, présenté sous le slogan « la France de la feuille de paie », prévoit une hausse du SMIC à 1 500 euros nets par mois, le passage à une semaine de travail de 32 heures sans baisse de rémunération, et une revalorisation des petites pensions à 1 200 euros net.', 'Europe 1', 'https://www.europe1.fr/politique/a-marseille-fabien-roussel-prone-la-france-de-la-feuille-de-paie-4092220', '2022-02-06', '2026-09-09', 'programme', 'SMIC, Temps de travail') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-87'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:fabien-roussel'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:international'), 'Sortie du commandement militaire intégré de l''OTAN', 'Sortir la France du commandement militaire intégré de l''OTAN et proposer une conférence de sécurité collective en Europe.', 'Dans son rapport introductif au Conseil national du PCF, Fabien Roussel réaffirme que « la France ne peut plus, ne doit plus participer à l''OTAN, dans son commandement militaire », au profit d''une architecture de sécurité collective européenne fondée sur la coopération entre les peuples.', 'Parti communiste français (pcf.fr)', 'https://www.pcf.fr/rapport_introductif_de_fabien_roussel_au_cn_du_10_01_2026', '2026-01-10', '2026-09-09', 'annonce', 'OTAN, Souveraineté') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-88'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:fabien-roussel'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:immigration'), 'Un débat sans tabou sur l''immigration à gauche', 'Appelle le PCF et la gauche à débattre ouvertement de la question migratoire plutôt que de l''éviter.', 'Invité de BFM TV, Fabien Roussel affirme qu''« il faut savoir parler de l''immigration » et que « la question de l''immigration, elle est posée, nous devons savoir en parler », sans se prononcer sur un chiffrage précis du niveau souhaité.', 'Actu Orange (BFM TV)', 'https://actu.orange.fr/videos/politique/pour-fabien-roussel-secretaire-national-du-pcf-il-faut-savoir-parler-de-l-immigration-CNT000002pXlUQ.html', '2026-06-14', '2026-09-09', 'annonce', 'Débat public') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-89'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:fabien-roussel'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:education'), 'Revenu étudiant à 850 euros et repas à 1 euro dans les cantines', 'Créer un revenu étudiant à partir de 850 euros par mois et généraliser le repas à 1 euro dans les cantines scolaires.', 'Le programme du PCF prévoit un revenu étudiant à partir de 850 euros par mois pour financer les études, et la généralisation du repas à 1 euro dans toutes les cantines scolaires.', 'Parti communiste français (pcf.fr)', 'https://www.pcf.fr/le_programme', '2026-09-06', '2026-09-09', 'programme', 'Revenu étudiant, Cantines') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-90'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:fabien-roussel'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:energie'), 'Un mix énergétique nucléaire et renouvelable', 'Défend un mix électrique combinant nucléaire et énergies renouvelables plutôt qu''une sortie du nucléaire.', 'Le programme du PCF défend explicitement « un mix énergétique nucléaire et renouvelable », une position qui distingue le parti d''autres forces de gauche favorables à une sortie du nucléaire.', 'Parti communiste français (pcf.fr)', 'https://www.pcf.fr/le_programme', '2026-09-06', '2026-09-09', 'programme', 'Nucléaire, Renouvelables') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-91'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nathalie-arthaud'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:pouvoir-achat'), 'Échelle mobile des salaires et des pensions', 'Indexer automatiquement les salaires et les pensions sur les prix, sous le contrôle des travailleurs eux-mêmes.', 'Lutte Ouvrière défend l''imposition d''une « échelle mobile des salaires et des pensions établie sous [le] propre contrôle » des travailleurs, pour empêcher que l''inflation n''appauvrisse mécaniquement les salariés et les retraités.', 'Lutte Ouvrière (lutte-ouvriere.org)', 'https://www.lutte-ouvriere.org/journal/article/2018-10-31-face-linflation-echelle-mobile_114571.html', '2018-10-31', '2026-09-09', 'programme', 'Salaires, Pensions') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-92'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nathalie-arthaud'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:economie'), 'Interdiction des licenciements sous peine de réquisition', 'Interdire les licenciements et réquisitionner les entreprises qui y procéderaient malgré tout.', 'Dans un éditorial signé par Nathalie Arthaud, Lutte Ouvrière défend l''« interdiction des licenciements sous peine de réquisition » comme réponse immédiate aux suppressions d''emplois annoncées par les grandes entreprises.', 'Lutte Ouvrière (lutte-ouvriere.org)', 'https://www.lutte-ouvriere.org/portail/editoriaux/interdiction-licenciements-sous-peine-requisition-184019.html', '2025-05-05', '2026-09-09', 'programme', 'Licenciements, Emploi') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-93'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nathalie-arthaud'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:economie'), 'Expropriation des banques et fusion en une seule entité contrôlée par la population', 'Exproprier les banques sans indemnité et les regrouper en une seule entité sous contrôle de la population.', 'Lutte Ouvrière propose d''exproprier les banques sans indemnité ni rachat et de les fusionner en une seule entité, placée sous le contrôle des travailleurs, des petits usagers et de la population, plutôt que sous celui des financiers.', 'Lutte Ouvrière (lutte-ouvriere.org)', 'https://www.lutte-ouvriere.org/journal/article/2008-10-10-moraliser-la-finance-commencerait-par-lexpropriation-des-responsables-de-la-crise_18488.html', '2008-10-10', '2026-09-09', 'programme', 'Banques') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-94'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nathalie-arthaud'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:immigration'), 'Liberté de circulation et d''installation pour tous les travailleurs', 'Défend la liberté de circulation et d''installation pour tous les travailleurs, quelle que soit leur nationalité.', 'Nathalie Arthaud affirme : « Nous sommes pour la liberté de circulation et d''installation de tous les travailleurs et donc pour la liberté des migrants de s''installer où ils le souhaitent », rejetant toute logique de quotas ou de fermeture des frontières au nom de la solidarité de classe entre travailleurs.', 'Breizh-info', 'https://www.breizh-info.com/2019/03/18/114345/nathalie-arthaud-lutte-ouvriere-travailleurs/', '2019-03-18', '2026-09-09', 'precision_ulterieure', 'Liberté de circulation') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-95'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nicolas-dupont-aignan'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:retraites'), 'Référendum pour maintenir la retraite à 62 ans', 'Propose un référendum d''initiative partagée pour maintenir l''âge légal de départ à 62 ans plutôt que de le reporter à 64 ans.', 'En janvier 2023, Nicolas Dupont-Aignan lance une procédure de référendum d''initiative partagée « pour ou contre le maintien de la retraite à 62 ans », qualifiant la réforme du gouvernement de réforme « abominable, inutile et injuste », en cherchant les 185 parlementaires nécessaires pour l''enclencher.', 'Public Sénat', 'https://www.publicsenat.fr/actualites/politique/retraites-une-reforme-abominable-inutile-et-injuste-pour-nicolas-dupont-aignan', '2023-01-16', '2026-09-09', 'annonce', 'Âge légal, Référendum') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-96'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nicolas-dupont-aignan'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:immigration'), 'Rétablir les frontières nationales et sortir de l''espace Schengen', 'Sortir de l''espace Schengen pour rétablir un contrôle national des frontières.', 'Premier des « 10 points du projet européen » de Debout la France : « Rétablir nos frontières nationales et sortir de l''espace Schengen », présenté comme préalable à toute politique migratoire nationale reprise en main.', 'Debout la France (debout-la-france.fr)', 'https://www.debout-la-france.fr/actualite/discours-de-rentree-les-10-points-du-projet-europeen-pour-une-france-libre-au-service-dun-monde-libre/', '2023-09-22', '2026-09-09', 'programme', 'Schengen, Frontières') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-97'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nicolas-dupont-aignan'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:europe'), 'Supprimer la Commission européenne et la Cour de justice de l''UE', 'Supprimer la Commission européenne et la CJUE, affirmer la primauté du droit français et réduire la contribution nette à l''UE à 1 milliard d''euros.', 'Le « projet européen » de Debout la France prévoit de « supprimer la Commission européenne », de « supprimer la Cour de Justice européenne », d''« affirmer la primauté du droit français sur le droit européen », et de « supprimer la contribution annuelle nette de la France de 10 milliards [d''euros] » pour n''en conserver qu''un, dédié aux coopérations volontaires.', 'Debout la France (debout-la-france.fr)', 'https://www.debout-la-france.fr/actualite/discours-de-rentree-les-10-points-du-projet-europeen-pour-une-france-libre-au-service-dun-monde-libre/', '2023-09-22', '2026-09-09', 'programme', 'Institutions européennes, Contribution UE') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-98'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nicolas-dupont-aignan'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:international'), 'Sortir du commandement militaire intégré de l''OTAN', 'Renouer avec une politique étrangère indépendante en sortant du commandement militaire intégré de l''OTAN.', 'Reprenant la doctrine gaulliste, Debout la France propose de « renouer avec une politique étrangère indépendante et sortir du commandement militaire intégré de l''OTAN », sans quitter l''Alliance atlantique elle-même.', 'Debout la France (debout-la-france.fr)', 'https://www.debout-la-france.fr/actualite/discours-de-rentree-les-10-points-du-projet-europeen-pour-une-france-libre-au-service-dun-monde-libre/', '2023-09-22', '2026-09-09', 'programme', 'OTAN, Souveraineté') on conflict (id) do nothing;
insert into proposals (id, candidate_id, theme_id, title, summary, description, source_name, source_url, published_at, verified_at, status, tags) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-99'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nicolas-dupont-aignan'), uuid_generate_v5(uuid_ns_url(), 'poliscope:theme:energie'), 'Maintenir le nucléaire et relancer une filière thorium', 'Maintenir le parc nucléaire et développer une filière thorium sur 25 à 30 ans en remplacement progressif de l''uranium.', 'Nicolas Dupont-Aignan défend le maintien du nucléaire dans le mix électrique et propose de « développer des réacteurs fonctionnant au thorium » pour succéder aux centrales à uranium, un combustible présenté comme plus sûr et générant des déchets radioactifs à durée de vie bien plus courte.', 'Techniques de l''Ingénieur', 'https://www.techniques-ingenieur.fr/actualite/articles/marine-pen-nicolas-dupont-aignan-42555/', '2017-04-20', '2026-09-09', 'precision_ulterieure', 'Nucléaire, Thorium') on conflict (id) do nothing;
insert into polls (id, election_id, institute, sponsor, field_start, field_end, sample_size, method, source_name, source_url, published_at, is_demo) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:poll:poll-ipsos-bva-le-parisien-2026-09'), uuid_generate_v5(uuid_ns_url(), 'poliscope:election:presidentielle-2027'), 'Ipsos bva CESI école d''ingénieurs', 'Le Parisien', '2026-08-31', '2026-09-02', 1500, 'Échantillon interrogé en ligne (Access panel Ipsos), représentatif de la population française de 18 ans et plus inscrite sur les listes électorales, selon la méthode des quotas (sexe, âge, profession, catégorie d''agglomération, région). Base pour cette hypothèse : 1 005 personnes certaines d''aller voter et exprimées.', 'Ipsos — Notice technique Commission des sondages', 'https://www.commission-des-sondages.fr/notices/files/notices/2026/septembre/10250-pres-iv-ipsos-bva-le-parisien-5-septembre.pdf', '2026-09-05', false) on conflict (id) do nothing;
