insert into poll_results (id, scenario_id, candidate_id, value, low, high) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:poll_result:poll-result-ipsos-2026-09-gp-6'), uuid_generate_v5(uuid_ns_url(), 'poliscope:poll_scenario:poll-scenario-ipsos-2026-09-glucksmann-philippe'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-tondelier'), 4, 2.8, 5.2) on conflict (id) do nothing;
insert into measure_analyses (id, proposal_id, status, summary, feasibility_status, precision_level, confidence_level, legal_path, legal_constitutional_change_required, legal_eu_change_required, legal_notes, legal_implementation_delay_min_months, legal_implementation_delay_max_months, implementation_existing_administration, implementation_new_recruitment_needed, implementation_notes, beneficiaries_groups, beneficiaries_description, beneficiaries_count_min, beneficiaries_count_central, beneficiaries_count_max, beneficiaries_source_name, beneficiaries_source_url, simulator_measure_id, reviewed_at, reviewed_by, published_at) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-71'), 'published', 'Le mécanisme (taux de TVA, produits concernés) est précisément défini par la source. Deux chiffrages indépendants existent et divergent selon les hypothèses retenues sur la réaction de la consommation à la baisse de prix — ils sont présentés côte à côte plutôt que fondus en une moyenne. Aucun effet macroéconomique (emploi, PIB, inflation) n''a été estimé par une source publique identifiée à ce jour.', 'faisable_sous_conditions', 'precise', 'moyenne', 'loi_finances', false, false, 'Un changement de taux de TVA relève du domaine de la loi de finances (article 34 de la Constitution) et peut être voté en loi de finances initiale ou rectificative. La source ne précise aucune mesure de compensation de la perte de recettes.', 1, 12, 'oui', 'non', 'La DGFiP applique déjà des taux de TVA différenciés selon les produits ; un changement de taux ne nécessite pas de nouvelle structure administrative ni de recrutement identifié par la source.', '["Ménages consommant gaz, fioul ou électricité","Automobilistes"]'::jsonb, 'Concerne la quasi-totalité des ménages français, à des degrés très variables selon leur consommation d''énergie et de carburant.', null, null, null, null, null, 'lepen-tva-energie', '2026-09-04', 'Équipe éditoriale Polysia', '2026-09-05') on conflict (id) do nothing;
insert into measure_analyses (id, proposal_id, status, summary, feasibility_status, precision_level, confidence_level, legal_path, legal_constitutional_change_required, legal_eu_change_required, legal_notes, legal_implementation_delay_min_months, legal_implementation_delay_max_months, implementation_existing_administration, implementation_new_recruitment_needed, implementation_notes, beneficiaries_groups, beneficiaries_description, beneficiaries_count_min, beneficiaries_count_central, beneficiaries_count_max, beneficiaries_source_name, beneficiaries_source_url, simulator_measure_id, reviewed_at, reviewed_by, published_at) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-2'), uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-2'), 'published', 'Le volet « hausse du SMIC » est un mécanisme clair (revalorisation à un montant net cible), déjà modélisé par le Simulateur d''impact de Polysia. Le volet « blocage des prix » n''est pas suffisamment défini par la source (produits concernés, durée, mécanisme de contrôle) pour être analysé séparément : cette fiche ne porte donc que sur la revalorisation du SMIC. Aucune source indépendante ne chiffre le coût budgétaire de cette mesure.', 'faisable_parametres_connus', 'partiellement_precis', 'moyenne', 'decret', false, false, 'Le montant du SMIC est fixé par décret pris en Conseil des ministres (article L3231-2 du code du travail), après avis de la Commission nationale de la négociation collective. Ce volet ne nécessite pas de loi.', 1, 3, 'oui', 'non', 'Le mécanisme de revalorisation du SMIC est un dispositif existant et récurrent (des revalorisations anticipées ont déjà été pratiquées par le passé).', '["Salariés rémunérés au SMIC"]'::jsonb, 'Salariés dont la rémunération nette est actuellement inférieure au seuil proposé de 1 600 €. Le chiffre ci-dessous porte sur les seuls salariés déjà au SMIC ; ceux situés entre le SMIC actuel et 1 600 € net ne sont pas comptabilisés, faute de source les isolant.', null, 2200000, null, 'DARES', 'https://dares.travail-emploi.gouv.fr/publication/combien-de-salaries-sont-remuneres-au-smic', 'melenchon-smic-1600', '2026-09-04', 'Équipe éditoriale Polysia', '2026-09-05') on conflict (id) do nothing;
insert into measure_analyses (id, proposal_id, status, summary, feasibility_status, precision_level, confidence_level, legal_path, legal_constitutional_change_required, legal_eu_change_required, legal_notes, legal_implementation_delay_min_months, legal_implementation_delay_max_months, implementation_existing_administration, implementation_new_recruitment_needed, implementation_notes, beneficiaries_groups, beneficiaries_description, beneficiaries_count_min, beneficiaries_count_central, beneficiaries_count_max, beneficiaries_source_name, beneficiaries_source_url, simulator_measure_id, reviewed_at, reviewed_by, published_at) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-3'), uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-73'), 'published', 'Le mécanisme proposé (un référendum sur un texte encadrant l''immigration) soulève une question juridique documentée et non tranchée par le Conseil constitutionnel : l''article 11 de la Constitution, qui définit les sujets pouvant être soumis à référendum, ne mentionne pas explicitement la politique migratoire parmi les matières autorisées. Le contenu précis du texte qui serait soumis au vote (barème, critères, calendrier) n''est en outre pas détaillé par la source.', 'obstacle_juridique_majeur', 'insuffisant', 'moyenne', 'referendum', true, false, 'L''article 11 de la Constitution limite les sujets pouvant être soumis à référendum (organisation des pouvoirs publics, réformes relatives à la politique économique, sociale ou environnementale, ratification de traités) ; la politique migratoire n''y figure pas explicitement. Plusieurs constitutionnalistes cités par la source estiment qu''une révision constitutionnelle serait nécessaire au préalable. Ce point fait débat et n''a pas été tranché par une décision du Conseil constitutionnel à ce jour.', null, null, 'non_documente', 'non_documente', null, '[]'::jsonb, null, null, null, null, null, null, null, '2026-09-04', 'Équipe éditoriale Polysia', '2026-09-05') on conflict (id) do nothing;
insert into measure_analyses (id, proposal_id, status, summary, feasibility_status, precision_level, confidence_level, legal_path, legal_constitutional_change_required, legal_eu_change_required, legal_notes, legal_implementation_delay_min_months, legal_implementation_delay_max_months, implementation_existing_administration, implementation_new_recruitment_needed, implementation_notes, beneficiaries_groups, beneficiaries_description, beneficiaries_count_min, beneficiaries_count_central, beneficiaries_count_max, beneficiaries_source_name, beneficiaries_source_url, simulator_measure_id, reviewed_at, reviewed_by, published_at) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-4'), uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-1'), 'published', 'Les paramètres sont clairement posés par la source : âge légal ramené à 60 ans, 40 annuités pour une carrière complète, pensions portées au niveau du SMIC revalorisé. Le chiffrage disponible émane d''un seul institut et couvre un périmètre plus large que cette proposition : ses composantes sont donc présentées séparément. Aucune source publique identifiée ne chiffre les effets de retour attendus par le candidat (baisse du chômage, hausse des cotisations).', 'faisable_parametres_connus', 'precise', 'moyenne', 'loi_ordinaire', false, false, 'L''âge légal et la durée de cotisation relèvent de la loi ordinaire — la réforme de 2023 a elle-même été portée par une loi de financement rectificative de la sécurité sociale. Aucune révision constitutionnelle ni négociation européenne n''est requise.', 6, 24, 'oui', 'non_documente', 'Les caisses de retraite appliquent déjà des paramètres d''âge et de durée ; leur modification ne suppose pas de nouvelle structure. Le volume de dossiers à traiter augmenterait fortement l''année de la bascule, sans que la source ne documente les moyens correspondants.', '["Actifs proches de l''âge de départ","Carrières longues"]'::jsonb, 'Concerne l''ensemble des actifs du secteur privé et public, avec un effet immédiat pour les générations proches de 60 ans. Aucune source identifiée ne chiffre le nombre exact de personnes concernées année par année.', null, null, null, null, null, 'melenchon-retraite-60', '2026-09-08', 'Équipe éditoriale Polysia', '2026-09-08') on conflict (id) do nothing;
insert into measure_analyses (id, proposal_id, status, summary, feasibility_status, precision_level, confidence_level, legal_path, legal_constitutional_change_required, legal_eu_change_required, legal_notes, legal_implementation_delay_min_months, legal_implementation_delay_max_months, implementation_existing_administration, implementation_new_recruitment_needed, implementation_notes, beneficiaries_groups, beneficiaries_description, beneficiaries_count_min, beneficiaries_count_central, beneficiaries_count_max, beneficiaries_source_name, beneficiaries_source_url, simulator_measure_id, reviewed_at, reviewed_by, published_at) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-5'), uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-72'), 'published', 'La mesure combine un âge légal ramené à 62 ans et un départ anticipé à 60 ans pour les carrières commencées tôt. Un institut indépendant en propose un chiffrage détaillé, avec une fourchette large qui traduit l''incertitude sur le nombre de personnes éligibles au départ anticipé. Aucun plan de financement n''est identifié par la source.', 'faisable_parametres_connus', 'partiellement_precis', 'moyenne', 'loi_ordinaire', false, false, 'Comme toute modification de l''âge légal et de la durée de cotisation, la mesure relève de la loi ordinaire ou d''une loi de financement de la sécurité sociale. La source ne précise pas le véhicule législatif retenu.', 6, 24, 'oui', 'non_documente', 'Le dispositif « carrières longues » existe déjà dans le droit en vigueur : son élargissement s''appuierait sur des règles de liquidation connues des caisses, sans création de structure nouvelle documentée.', '["Actifs proches de 62 ans","Personnes ayant commencé à travailler avant 20 ans"]'::jsonb, 'Selon l''institut ayant chiffré la mesure, environ 57 % de la génération 1962 avait validé des trimestres avant 20 ans et relèverait donc du volet « carrières longues ». Cette proportion ne peut pas être convertie en un effectif annuel sans hypothèse supplémentaire, qui n''est pas documentée.', null, null, null, 'Institut Montaigne', 'https://www.institutmontaigne.org/legislatives-2024/rassemblement-national/abroger-la-reforme-des-retraites-et-pour-ceux-ayant-commence-a-travailler-avant-20-ans-partir-a-40-annuites-de-cotisations/', 'lepen-retraite-62', '2026-09-08', 'Équipe éditoriale Polysia', '2026-09-08') on conflict (id) do nothing;
insert into measure_analyses (id, proposal_id, status, summary, feasibility_status, precision_level, confidence_level, legal_path, legal_constitutional_change_required, legal_eu_change_required, legal_notes, legal_implementation_delay_min_months, legal_implementation_delay_max_months, implementation_existing_administration, implementation_new_recruitment_needed, implementation_notes, beneficiaries_groups, beneficiaries_description, beneficiaries_count_min, beneficiaries_count_central, beneficiaries_count_max, beneficiaries_source_name, beneficiaries_source_url, simulator_measure_id, reviewed_at, reviewed_by, published_at) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-6'), uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-43'), 'published', 'La cible est claire — 20 % de hausse de la rémunération moyenne sur un quinquennat — et la population concernée est précisément dénombrée par la statistique publique. En revanche, aucun chiffrage indépendant du coût n''a pu être identifié, pas même pour éprouver l''affirmation du candidat selon laquelle la baisse du nombre d''élèves suffirait à financer la mesure sans dégrader les finances publiques. Le coût est donc affiché comme non chiffré plutôt qu''estimé.', 'faisable_sous_conditions', 'partiellement_precis', 'faible', 'loi_finances', false, false, 'La rémunération des enseignants titulaires relève du statut de la fonction publique : une revalorisation générale passe par décret indiciaire, mais son financement suppose une inscription en loi de finances. La source ne détaille ni la ventilation entre point d''indice, primes et heures supplémentaires, ni le calendrier annuel.', 12, 60, 'oui', 'non', 'La mesure porte sur la rémunération d''agents déjà en poste : elle ne suppose ni structure nouvelle, ni recrutement. Le candidat mentionne en revanche de « nouvelles conditions professionnelles » en contrepartie, sans que leur contenu soit précisé.', '["Enseignants du public","Enseignants du privé sous contrat"]'::jsonb, 'L''ensemble des enseignants de l''enseignement scolaire. La source ne précise pas si le privé sous contrat, dont les maîtres sont rémunérés par l''État, est inclus dans le périmètre.', 712800, 852800, 852800, 'DEPP — L''éducation nationale en chiffres, édition 2025', 'https://www.education.gouv.fr/sites/default/files/2025-08/l-ducation-nationale-en-chiffres-dition-2025-441804.pdf', 'philippe-enseignants', '2026-09-08', 'Équipe éditoriale Polysia', '2026-09-08') on conflict (id) do nothing;
insert into measure_budget_estimates (id, measure_analysis_id, source_type, source_name, source_url, annual_cost_min, annual_cost_central, annual_cost_max, annual_revenue_min, annual_revenue_central, annual_revenue_max, currency, reference_year, financing_identified, notes) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_budget_estimate:measure-analysis-1-budget-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-1'), 'independent_body', 'Ministère de l''Économie et des Finances (chiffrage cité par Public Sénat)', 'https://www.publicsenat.fr/actualites/politique/baisse-de-la-tva-sur-lenergie-proposee-par-le-rn-une-mesure-chiffree-a-17-milliards-selon-bercy', 16.8, 16.8, 16.8, null, null, null, 'Md€', 2026, 'non', 'Détail du chiffrage : électricité 4,5 Md€ + gaz 2,3 Md€ + carburants 10 Md€ = 16,8 Md€. Couvre l''ensemble des postes visés par la mesure.') on conflict (id) do nothing;
insert into measure_budget_estimates (id, measure_analysis_id, source_type, source_name, source_url, annual_cost_min, annual_cost_central, annual_cost_max, annual_revenue_min, annual_revenue_central, annual_revenue_max, currency, reference_year, financing_identified, notes) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_budget_estimate:measure-analysis-1-budget-2'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-1'), 'other', 'Institut Montaigne (think tank libéral)', 'https://www.institutmontaigne.org/legislatives-2024/rassemblement-national/baisser-la-tva-de-20-a-55-pour-les-carburants-lelectricite-le-gaz-et-le-fioul-domestique/', 9, 11.5, 14, null, null, null, 'Md€', 2024, 'non', 'Estimation republiée à l''occasion des législatives 2024 (une estimation antérieure du même institut, en 2022, chiffrait la mesure à 10 Md€/an). L''écart avec le chiffrage de Bercy tient notamment aux hypothèses retenues sur la réaction de la consommation à la baisse de prix.') on conflict (id) do nothing;
insert into measure_budget_estimates (id, measure_analysis_id, source_type, source_name, source_url, annual_cost_min, annual_cost_central, annual_cost_max, annual_revenue_min, annual_revenue_central, annual_revenue_max, currency, reference_year, financing_identified, notes) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_budget_estimate:measure-analysis-4-budget-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-4'), 'independent_body', 'Institut Montaigne — composante « retour à l''âge de 60 ans »', 'https://www.institutmontaigne.org/legislatives-2024/nouveau-front-populaire/abroger-la-reforme-des-retraites-restaurer-la-retraite-a-60-ans-en-prenant-en-compte-le-rsa-en-portant-le-minimum-contributif-au-smic/', null, 27, null, null, null, null, 'Md€', 2027, 'non', 'Composante isolée par l''institut au sein d''un chiffrage plus large : le retour à 60 ans (annulation de la réforme de 2010) est évalué à 27 Md€, l''abrogation de la réforme de 2023 à 8,2 Md€ supplémentaires. C''est la ligne qui correspond le plus directement à cette proposition.') on conflict (id) do nothing;
insert into measure_budget_estimates (id, measure_analysis_id, source_type, source_name, source_url, annual_cost_min, annual_cost_central, annual_cost_max, annual_revenue_min, annual_revenue_central, annual_revenue_max, currency, reference_year, financing_identified, notes) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_budget_estimate:measure-analysis-4-budget-2'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-4'), 'independent_body', 'Institut Montaigne — ensemble du volet retraites chiffré', 'https://www.institutmontaigne.org/legislatives-2024/nouveau-front-populaire/abroger-la-reforme-des-retraites-restaurer-la-retraite-a-60-ans-en-prenant-en-compte-le-rsa-en-portant-le-minimum-contributif-au-smic/', 49, 58, 67, null, null, null, 'Md€', 2027, 'non', 'Périmètre plus large que cette proposition : au retour à 60 ans et à l''abrogation de 2023 s''ajoutent la revalorisation du minimum contributif au SMIC (13,9 Md€), celle du minimum vieillesse (0,7 Md€) et la prise en compte des années de RSA (8,4 Md€). La fourchette reflète une marge de ±15 % appliquée par l''institut. Chiffrage limité au régime de retraite, sans les autres effets sur les finances sociales.') on conflict (id) do nothing;
insert into measure_budget_estimates (id, measure_analysis_id, source_type, source_name, source_url, annual_cost_min, annual_cost_central, annual_cost_max, annual_revenue_min, annual_revenue_central, annual_revenue_max, currency, reference_year, financing_identified, notes) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_budget_estimate:measure-analysis-5-budget-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-5'), 'independent_body', 'Institut Montaigne', 'https://www.institutmontaigne.org/legislatives-2024/rassemblement-national/abroger-la-reforme-des-retraites-et-pour-ceux-ayant-commence-a-travailler-avant-20-ans-partir-a-40-annuites-de-cotisations/', 31.5, 34.7, 44.7, null, null, null, 'Md€', 2027, 'non', 'Chiffrage portant sur l''abrogation de la réforme de 2023 et le retour partiel sur les réformes de 2003 à 2014. L''ampleur de la fourchette tient à la part de la population éligible au départ anticipé : l''institut retient environ 57 % de la génération 1962 ayant validé des trimestres avant 20 ans.') on conflict (id) do nothing;
insert into measure_impacts (id, measure_analysis_id, impact_type, horizon, scenario, population, value_min, value_central, value_max, unit, confidence_level, method, source_name, source_url, scenario_assumptions, publication_date) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_impact:measure-analysis-1-impact-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-1'), 'revenu_menages', 'court', 'unique', 'Ménage selon son profil de consommation d''énergie et de carburant', 7, 26, 41, '€/mois', 'moyenne', 'Calcul direct : application du nouveau taux de TVA à la dépense d''énergie et de carburant déclarée (voir Simulateur d''impact de Polysia). Fourchette illustrative entre un profil faiblement et fortement consommateur ; ne prend pas en compte un éventuel effet sur les prix hors taxe.', null, null, null, '2026-09-04') on conflict (id) do nothing;
insert into measure_impacts (id, measure_analysis_id, impact_type, horizon, scenario, population, value_min, value_central, value_max, unit, confidence_level, method, source_name, source_url, scenario_assumptions, publication_date) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_impact:measure-analysis-2-impact-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-2'), 'revenu_menages', 'court', 'unique', 'Salarié actuellement rémunéré entre le SMIC et 1 600 € net', 50, null, 300, '€/mois', 'moyenne', 'Calcul direct : 1 600 € − salaire net actuel déclaré, pour les salariés rémunérés en dessous de ce seuil (voir Simulateur d''impact de Polysia). Pas de scénario central pertinent : le gain dépend entièrement du salaire de départ.', null, null, null, '2026-09-04') on conflict (id) do nothing;
insert into measure_assumptions (id, measure_analysis_id, name, value, unit, assumption_type, justification, source_name, source_url) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_assumption:measure-analysis-1-assumption-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-1'), 'Taux de TVA cible', '5,5', '%', 'candidate', 'Taux annoncé par la source pour l''électricité, le gaz, le fioul et les carburants.', 'CNEWS (amendement RN au budget 2026)', 'https://www.cnews.fr/france/2025-10-21/abaissement-de-la-tva-55-quels-produits-sont-concernes-par-lamendement-depose-par') on conflict (id) do nothing;
insert into measure_assumptions (id, measure_analysis_id, name, value, unit, assumption_type, justification, source_name, source_url) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_assumption:measure-analysis-1-assumption-2'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-1'), 'Consommation de carburant (calcul individuel)', '6,5', 'L/100 km', 'manual_assumption', 'Hypothèse technique déjà utilisée par le Simulateur d''impact de Polysia pour convertir un kilométrage annuel en dépense de carburant.', null, null) on conflict (id) do nothing;
