insert into candidate_position_history (id, candidate_id, theme_id, subject, position_summary, quote, date, source_name, source_url, source_type, status, verified_at) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_position_history:candidate-position-history-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:jean-luc-melenchon'), null, 'Port du voile islamique', 'Sur son blog, à propos du voile intégral (niqab/burqa), il décrit son port comme un traitement dégradant pour la femme qui le porte et plaide pour son interdiction dans l''espace public.', 'Mon point de départ est que le port de ce voile est un traitement dégradant pour la personne qui s''y soumet.', '2010-01-07', 'Blog de Jean-Luc Mélenchon', 'https://melenchon.fr/2010/01/07/je-parle-du-voile-integral/', 'candidate', 'published', '2026-09-10') on conflict (id) do nothing;
insert into candidate_position_history (id, candidate_id, theme_id, subject, position_summary, quote, date, source_name, source_url, source_type, status, verified_at) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_position_history:candidate-position-history-2'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:jean-luc-melenchon'), null, 'Port du voile islamique', 'Interrogé sur le port du voile islamique dans « L''Émission politique » (France 2), il dit ne pas en comprendre le sens religieux et affirme son opposition à l''ensemble des signes religieux.', 'Je ne vois pas en quoi Dieu serait intéressé par un chiffon sur la tête.', '2017-02-23', 'Franceinfo', 'https://www.franceinfo.fr/politique/j-ai-fait-une-erreur-terrible-jean-luc-melenchon-admet-avoir-change-d-avis-sur-le-port-du-voile-islamique_8175281.html', 'media', 'published', '2026-09-10') on conflict (id) do nothing;
insert into candidate_position_history (id, candidate_id, theme_id, subject, position_summary, quote, date, source_name, source_url, source_type, status, verified_at) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_position_history:candidate-position-history-3'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:jean-luc-melenchon'), null, 'Port du voile islamique', 'Il déclare publiquement avoir changé d''avis sur le port du voile islamique, qualifiant ses positions passées d''« erreur terrible », après avoir échangé avec des femmes concernées.', 'J''ai rencontré des femmes qui portaient le voile [...] j''ai été convaincu et j''ai changé d''avis. Je me suis dit que j''ai fait une erreur terrible.', '2026-09-02', 'Franceinfo', 'https://www.franceinfo.fr/politique/j-ai-fait-une-erreur-terrible-jean-luc-melenchon-admet-avoir-change-d-avis-sur-le-port-du-voile-islamique_8175281.html', 'media', 'published', '2026-09-10') on conflict (id) do nothing;
insert into candidate_position_history (id, candidate_id, theme_id, subject, position_summary, quote, date, source_name, source_url, source_type, status, verified_at) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_position_history:candidate-position-history-4'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-le-pen'), null, 'Sortie de l''euro', 'Lors de la présentation de ses « 144 engagements présidentiels » aux assises de Lyon, elle défend le rétablissement d''une monnaie nationale, présenté comme un levier de compétitivité économique.', 'rétablissement d''une monnaie nationale adaptée à notre économie, levier de notre compétitivité', '2017-02-05', 'Public Sénat', 'https://www.publicsenat.fr/actualites/non-classe/sur-l-europe-marine-le-pen-a-t-elle-vraiment-change-202482', 'media', 'published', '2026-09-10') on conflict (id) do nothing;
insert into candidate_position_history (id, candidate_id, theme_id, subject, position_summary, quote, date, source_name, source_url, source_type, status, verified_at) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_position_history:candidate-position-history-5'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-le-pen'), null, 'Sortie de l''euro', 'Lors de ses vœux à la presse, elle affirme que sortir de l''euro n''est plus une priorité, tout en continuant à qualifier la monnaie unique de problématique pour la France.', 'Incontestablement, l''euro est un boulet pour la France, [...] en sortir n''est plus une priorité.', '2019-01-17', 'Public Sénat', 'https://www.publicsenat.fr/actualites/non-classe/sur-l-europe-marine-le-pen-a-t-elle-vraiment-change-202482', 'media', 'published', '2026-09-10') on conflict (id) do nothing;
insert into candidate_position_evolutions (id, candidate_id, theme_id, subject, evolution_type, confidence, summary, candidate_explanation, candidate_explanation_source_url, status, verified_at) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_position_evolution:candidate-position-evolution-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:jean-luc-melenchon'), null, 'Port du voile islamique', 'position_reversed', 'evolved', 'Jean-Luc Mélenchon a publiquement reconnu avoir changé d''avis sur le port du voile islamique : après avoir qualifié le voile intégral de « traitement dégradant » en 2010 et le port du voile en général de « chiffon sur la tête » en 2017, il affirme désormais que sa position passée était une erreur. Sa déclaration de 2010 portait spécifiquement sur le voile intégral (niqab/burqa) ; celle de 2017 sur le port du voile de façon plus générale.', '« J''ai rencontré des femmes qui portaient le voile [...] j''ai été convaincu et j''ai changé d''avis. Je me suis dit que j''ai fait une erreur terrible. »', 'https://www.franceinfo.fr/politique/j-ai-fait-une-erreur-terrible-jean-luc-melenchon-admet-avoir-change-d-avis-sur-le-port-du-voile-islamique_8175281.html', 'published', '2026-09-10') on conflict (id) do nothing;
insert into candidate_position_evolutions (id, candidate_id, theme_id, subject, evolution_type, confidence, summary, candidate_explanation, candidate_explanation_source_url, status, verified_at) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_position_evolution:candidate-position-evolution-2'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-le-pen'), null, 'Sortie de l''euro', 'position_reversed', 'evolved', 'Marine Le Pen a abandonné sa proposition de sortie de l''euro entre sa campagne présidentielle de 2017, où elle défendait le rétablissement d''une monnaie nationale, et janvier 2019, où elle a déclaré que sortir de l''euro n''était plus une priorité — tout en continuant à qualifier l''euro de problématique pour la France.', 'Elle a évoqué une proposition « perçue comme brutale » ayant entraîné « une véritable crainte », plaidant depuis pour une reconquête de la souveraineté « progressive » plutôt que brutale.', 'https://www.publicsenat.fr/actualites/non-classe/sur-l-europe-marine-le-pen-a-t-elle-vraiment-change-202482', 'published', '2026-09-10') on conflict (id) do nothing;
insert into candidate_legal_cases (id, candidate_id, title, case_type, summary, legal_status, jurisdiction, start_date, decision_date, last_updated, next_review_at, source_name, source_url, source_type, status) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_legal_case:candidate-legal-case-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-le-pen'), 'Affaire des assistants parlementaires du RN au Parlement européen', 'Détournement de fonds publics', 'Marine Le Pen a été condamnée le 31 mars 2025 par le tribunal correctionnel de Paris à 4 ans de prison (dont 2 ans aménageables sous surveillance électronique, 2 ans avec sursis), 100 000 € d''amende et 5 ans d''inéligibilité exécutoire immédiatement, pour détournement de fonds publics dans l''affaire des emplois d''assistants parlementaires du Front national/Rassemblement national au Parlement européen (faits visés : 2004-2016). En appel, la cour d''appel de Paris l''a condamnée à nouveau le 7 juillet 2026, avec une peine réduite : 3 ans de prison (dont 1 an ferme aménageable sous bracelet électronique, 2 ans avec sursis), 100 000 € d''amende et 45 mois d''inéligibilité (dont 30 mois avec sursis). Elle a annoncé se pourvoir en cassation.', 'convicted_on_appeal', 'Cour d''appel de Paris', null, '2026-07-07', '2026-09-10', null, 'Toute l''Europe', 'https://www.touteleurope.eu/vie-politique-des-etats-membres/proces-des-assistants-du-rn-marine-le-pen-condamnee-en-appel-mais-eligible-a-l-election-presidentielle-2027/', 'media', 'published') on conflict (id) do nothing;
insert into candidate_legal_cases (id, candidate_id, title, case_type, summary, legal_status, jurisdiction, start_date, decision_date, last_updated, next_review_at, source_name, source_url, source_type, status) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_legal_case:candidate-legal-case-2'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:jean-luc-melenchon'), 'Perquisition houleuse au siège de La France insoumise (2018)', 'Intimidation envers un magistrat et un dépositaire de l''autorité publique, rébellion, provocation', 'Le 16 octobre 2018, lors d''une perquisition au siège de La France insoumise et à son domicile menée dans le cadre d''enquêtes sur des emplois présumés fictifs d''assistants parlementaires européens et sur les comptes de campagne de 2017, Jean-Luc Mélenchon a bousculé des représentants du parquet et forcé le passage. Il a été condamné le 9 décembre 2019 par le tribunal correctionnel de Bobigny à trois mois de prison avec sursis et 8 000 € d''amende. Il a annoncé publiquement ne pas faire appel.', 'convicted_final', 'Tribunal correctionnel de Bobigny', '2018-10-16', '2019-12-09', '2026-09-10', null, 'Franceinfo', 'https://www.franceinfo.fr/politique/melenchon/perquisition-mouvementee-a-la-france-insoumise-jean-luc-melenchon-condamne-a-trois-mois-de-prison-avec-sursis-et-8-000-euros-d-amende_3737089.html', 'media', 'published') on conflict (id) do nothing;
insert into candidate_legal_cases (id, candidate_id, title, case_type, summary, legal_status, jurisdiction, start_date, decision_date, last_updated, next_review_at, source_name, source_url, source_type, status) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_legal_case:candidate-legal-case-3'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:jean-luc-melenchon'), 'Enquête sur les assistants parlementaires de La France insoumise au Parlement européen', 'Soupçon d''emploi fictif d''assistants parlementaires', 'Jean-Luc Mélenchon et d''anciens assistants parlementaires étaient visés, depuis un signalement de l''Office européen de lutte antifraude (OLAF) en 2017 puis une enquête judiciaire française ouverte en 2018, par des soupçons d''avoir employé des assistants du Parlement européen pour soutenir principalement son activité politique nationale — un mécanisme similaire à celui jugé dans l''affaire visant le Rassemblement national. Après huit ans d''instruction, les juges ont clos le dossier le 26 mai 2026 sans mise en examen de Jean-Luc Mélenchon. Deux anciens assistants restent sous statut de témoin assisté.', 'closed_without_action', null, null, '2026-05-26', '2026-09-10', null, 'Franceinfo', 'https://www.franceinfo.fr/politique/la-france-insoumise/enquete-sur-les-assistants-parlementaires-de-lfi-l-instruction-est-close-sans-mise-en-examen_8029814.html', 'media', 'published') on conflict (id) do nothing;
insert into candidate_legal_cases (id, candidate_id, title, case_type, summary, legal_status, jurisdiction, start_date, decision_date, last_updated, next_review_at, source_name, source_url, source_type, status) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_legal_case:candidate-legal-case-4'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:xavier-bertrand'), 'Diffamation envers Mediapart', 'Diffamation', 'Le 6 juillet 2010, en marge d''un meeting au Raincy, Xavier Bertrand, alors secrétaire général de l''UMP, avait accusé le site Mediapart d''utiliser des « méthodes fascisantes » à propos de ses révélations dans l''affaire Bettencourt. Mediapart avait porté plainte pour diffamation. Le tribunal correctionnel de Paris l''a relaxé le 26 mars 2013, jugeant que ses propos ne visaient pas un fait précis. Mediapart avait indiqué vouloir poursuivre le débat judiciaire ; Polysia n''a pas trouvé de confirmation sourcée d''une décision d''appel.', 'acquitted', 'Tribunal correctionnel de Paris', null, '2013-03-26', '2026-09-10', null, 'Le Nouvelliste', 'https://www.lenouvelliste.ch/monde/xavier-bertrand-relaxe-des-poursuites-de-mediapart-264658', 'media', 'published') on conflict (id) do nothing;
insert into candidate_legal_cases (id, candidate_id, title, case_type, summary, legal_status, jurisdiction, start_date, decision_date, last_updated, next_review_at, source_name, source_url, source_type, status) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_legal_case:candidate-legal-case-5'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:edouard-philippe'), 'Mise en cause pour la gestion de la crise du Covid-19', 'Mise en cause devant la Cour de justice de la République', 'Une information judiciaire a été ouverte en 2020 devant la Cour de justice de la République (CJR), seule juridiction compétente pour juger les membres du gouvernement pour des actes commis dans l''exercice de leurs fonctions, visant notamment l''ancien Premier ministre Édouard Philippe pour « mise en danger de la vie d''autrui » et « abstention volontaire de combattre un sinistre » dans la gestion de la crise sanitaire. Entendu en octobre 2022, il a été placé sous le statut de témoin assisté, sans mise en examen. La CJR a prononcé un non-lieu à son égard le 7 juillet 2025.', 'dismissed', 'Cour de justice de la République', null, '2025-07-07', '2026-09-10', null, 'Le Club des Juristes', 'https://www.leclubdesjuristes.com/en-bref/gestion-du-covid-19-la-cjr-prononce-un-non-lieu-a-lencontre-de-edouard-philippe-agnes-buzyn-et-olivier-veran-11443/', 'media', 'published') on conflict (id) do nothing;
insert into candidate_legal_cases (id, candidate_id, title, case_type, summary, legal_status, jurisdiction, start_date, decision_date, last_updated, next_review_at, source_name, source_url, source_type, status) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_legal_case:candidate-legal-case-6'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nicolas-dupont-aignan'), 'Propos sur l''« invasion migratoire » (tweet de 2017)', 'Provocation à la haine ou à la discrimination', 'Après un tweet du 17 janvier 2017 évoquant une « invasion migratoire », la Licra avait porté plainte contre Nicolas Dupont-Aignan pour provocation à la haine ou à la discrimination. Le tribunal de Paris (17e chambre correctionnelle) l''a relaxé le 6 juin 2018, estimant que l''infraction n''était pas caractérisée ; ses avocats invoquaient par ailleurs l''immunité parlementaire, argument que le tribunal n''a pas retenu.', 'acquitted', 'Tribunal de Paris (17e chambre correctionnelle)', null, '2018-06-06', '2026-09-10', null, 'Public Sénat', 'https://www.publicsenat.fr/actualites/politique/dupont-aignan-relaxe-pour-ses-propos-sur-l-invasion-migratoire-en-france-86680', 'media', 'published') on conflict (id) do nothing;
insert into candidate_legal_cases (id, candidate_id, title, case_type, summary, legal_status, jurisdiction, start_date, decision_date, last_updated, next_review_at, source_name, source_url, source_type, status) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_legal_case:candidate-legal-case-7'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:marine-le-pen'), 'Propos comparant les prières de rue à l''Occupation', 'Provocation à la discrimination, à la haine ou à la violence en raison de la religion', 'En décembre 2010, lors d''une réunion publique à Lyon, Marine Le Pen avait comparé les prières de rue de fidèles musulmans à une « occupation ». Poursuivie à partir de 2012 pour provocation à la discrimination, à la haine ou à la violence en raison de la religion, après la levée de son immunité de députée européenne, elle a été jugée le 20 octobre 2015 par le tribunal correctionnel de Lyon. Le ministère public avait lui-même requis la relaxe. Elle a été relaxée le 15 décembre 2015.', 'acquitted', 'Tribunal correctionnel de Lyon', null, '2015-12-15', '2026-09-10', null, 'France 24', 'https://www.france24.com/fr/20151215-marine-le-pen-relaxe-prieres-rue-musulman-occupation-nazie-france', 'media', 'published') on conflict (id) do nothing;
insert into candidate_legal_cases (id, candidate_id, title, case_type, summary, legal_status, jurisdiction, start_date, decision_date, last_updated, next_review_at, source_name, source_url, source_type, status) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_legal_case:candidate-legal-case-8'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:fabien-roussel'), 'Poursuites du Rassemblement national pour diffamation', 'Diffamation (poursuites engagées par le Rassemblement national)', 'En octobre 2019, après avoir mis en cause l''implication de militants d''extrême droite dans des actions violentes, dont l''attaque de la mosquée de Bayonne, sur le plateau des « 4 vérités » (France 2), Fabien Roussel a été poursuivi pour diffamation par le Rassemblement national devant le tribunal correctionnel de Paris. Il a été relaxé le 27 janvier 2022, le tribunal retenant l''excuse de bonne foi. La cour d''appel de Paris a confirmé cette relaxe le 15 décembre 2022 et débouté le RN de l''ensemble de ses demandes.', 'acquitted', 'Cour d''appel de Paris', null, '2022-12-15', '2026-09-10', null, 'PCF (compte-rendu de la décision)', 'https://www.pcf.fr/le_rassemblement_national_d_bout_de_son_action_en_justice_contre_fabien_roussel', 'candidate', 'published') on conflict (id) do nothing;
insert into candidate_legal_cases (id, candidate_id, title, case_type, summary, legal_status, jurisdiction, start_date, decision_date, last_updated, next_review_at, source_name, source_url, source_type, status) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_legal_case:candidate-legal-case-9'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:fabien-roussel'), 'Soupçon d''emploi fictif comme assistant parlementaire', 'Soupçon d''emploi fictif d''assistant parlementaire', 'Selon Mediapart, Fabien Roussel aurait occupé un emploi fictif d''assistant parlementaire auprès du député Jean-Jacques Candelier entre 2009 et 2014, pour un salaire mensuel de 3 000 €. Il conteste les accusations, affirmant avoir réellement suivi les dossiers du Douaisis pour ce mandat. Le Parquet national financier a ouvert une enquête préliminaire en mars 2022 ; elle était toujours en cours à la dernière vérification publique de ce dossier (21 février 2026), sans mise en examen ni décision de justice à ce stade.', 'investigation', 'Parquet national financier', null, null, '2026-09-10', null, 'Poligraph', 'https://poligraph.fr/affaires/fabien-roussel-soupcons-d-emploi-fictif-comme-assistant-parlementaire', 'media', 'published') on conflict (id) do nothing;
insert into candidate_legal_cases (id, candidate_id, title, case_type, summary, legal_status, jurisdiction, start_date, decision_date, last_updated, next_review_at, source_name, source_url, source_type, status) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_legal_case:candidate-legal-case-10'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:francois-ruffin'), 'Diffamation envers un habitant d''Amiens Nord (livre « Quartier Nord »)', 'Diffamation', 'Dans son livre « Quartier Nord » (2006), François Ruffin avait désigné sous un pseudonyme un habitant du quartier, Nourédine Gaham, avec des formules dégradantes et des accusations non étayées. Ce dernier a porté plainte pour diffamation ; le tribunal correctionnel d''Amiens a condamné François Ruffin le 23 avril 2008. Polysia n''a pas trouvé de source confirmant un appel de cette décision.', 'convicted_final', 'Tribunal correctionnel d''Amiens', null, '2008-04-23', '2026-09-10', null, 'Franceinfo', 'https://www.franceinfo.fr/societe/nuit-debout/journalisme-engage-critique-des-medias-et-france-peripherique-qui-est-francois-ruffin-l-inspirateur-de-nuit-debout_1413979.html', 'media', 'published') on conflict (id) do nothing;
insert into candidate_controversies (id, candidate_id, title, summary, event_date, context, candidate_response, candidate_response_source_url, controversy_status, last_updated, next_review_at, source_name, source_url, source_type, status) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_controversy:candidate-controversy-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:nicolas-dupont-aignan'), 'Sanctionné par l''Assemblée nationale pour avoir voté à la place d''un collègue absent', 'Lors d''un vote sur un projet de loi relatif à la gestion de la crise sanitaire, fin juillet 2021, Nicolas Dupont-Aignan a voté depuis le boîtier de son collègue José Évrard, absent. Le Bureau de l''Assemblée nationale l''a sanctionné le 13 octobre 2021 pour « fraude au scrutin » : rappel au règlement et retrait d''un quart de son indemnité parlementaire pour un mois.', '2021-10-13', 'Nicolas Dupont-Aignan a récusé le terme de « fraude », évoquant une « erreur » et un « quiproquo administratif » : il affirme avoir reçu une délégation de vote de José Évrard, mais qu''un document nécessaire à la procédure n''aurait pas été transmis à temps.', null, null, 'disputed', '2026-09-11', null, 'LCP — Assemblée nationale', 'https://lcp.fr/actualites/nicolas-dupont-aignan-sanctionne-par-l-assemblee-le-depute-recuse-la-fraude-et-concede', 'media', 'published') on conflict (id) do nothing;
insert into candidate_controversies (id, candidate_id, title, summary, event_date, context, candidate_response, candidate_response_source_url, controversy_status, last_updated, next_review_at, source_name, source_url, source_type, status) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_controversy:candidate-controversy-2'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:david-lisnard'), 'Arrêté municipal interdisant le burkini sur les plages de Cannes', 'Le 28 juillet 2016, quelques jours après l''attentat de Nice, David Lisnard, maire de Cannes, a pris un arrêté municipal interdisant le port de tenues manifestant de façon ostensible une appartenance religieuse sur les plages de la commune — mesure connue sous le nom d''« arrêté anti-burkini ». Plusieurs arrêtés municipaux comparables ont été pris dans d''autres communes du littoral. Le Conseil d''État a jugé le 26 août 2016, sur un arrêté similaire de Villeneuve-Loubet, qu''une telle interdiction portait une atteinte grave et illégale aux libertés fondamentales ; l''arrêté cannois a ensuite été suspendu.', '2016-07-28', 'L''arrêté a été contesté en justice par le Collectif contre l''islamophobie en France (CCIF) et critiqué par SOS Racisme. David Lisnard l''a défendu au nom de l''ordre public dans le contexte des attentats de 2016 ; ses détracteurs y ont vu une stigmatisation des musulmans.', null, null, 'documented', '2026-09-11', null, 'France 24', 'https://www.france24.com/fr/20160812-arrete-burkini-cannes-deux-associations-poursuivre-maire-cannes-justice-islam', 'media', 'published') on conflict (id) do nothing;
insert into candidate_controversies (id, candidate_id, title, summary, event_date, context, candidate_response, candidate_response_source_url, controversy_status, last_updated, next_review_at, source_name, source_url, source_type, status) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_controversy:candidate-controversy-3'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:bruno-retailleau'), 'Propos sur l''État de droit « ni intangible, ni sacré »', 'Dans un entretien au Journal du dimanche publié le 29 septembre 2024, alors ministre de l''Intérieur, Bruno Retailleau déclare : « L''État de droit, ça n''est pas intangible, ni sacré », ajoutant que « la source de l''État de droit, c''est la démocratie, c''est le peuple souverain ». La formule provoque une controverse politique et institutionnelle immédiate.', '2024-09-29', 'Parmi les réactions critiques : la présidente de l''Assemblée nationale Yaël Braun-Pivet, l''ancienne Première ministre Élisabeth Borne, le Syndicat de la magistrature et la Ligue des droits de l''Homme. Une motion de censure visant notamment ces propos a été déposée le 4 octobre 2024 par des députés du Nouveau Front populaire. Des parlementaires Les Républicains ont au contraire soutenu le ministre, affirmant qu''il évoquait « l''état du droit » et non « l''État de droit ».', 'Dans un communiqué publié le 1er octobre 2024, il dénonce de « faux débats » et affirme : « Bien sûr qu''il ne peut y avoir de démocratie sans État de droit. C''est là le fondement de notre République. »', 'https://www.franceinfo.fr/politique/bruno-retailleau-regrette-de-faux-debats-au-sujet-de-ses-propos-sur-l-etat-de-droit-fondement-de-notre-republique_6811960.html', 'disputed', '2026-09-11', null, 'Franceinfo', 'https://www.franceinfo.fr/politique/gouvernement-de-michel-barnier/l-etat-de-droit-ca-n-est-pas-intangible-ni-sacre-pourquoi-les-propos-du-ministre-de-l-interieur-bruno-retailleau-font-polemique_6810349.html', 'media', 'published') on conflict (id) do nothing;
insert into candidate_controversies (id, candidate_id, title, summary, event_date, context, candidate_response, candidate_response_source_url, controversy_status, last_updated, next_review_at, source_name, source_url, source_type, status) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_controversy:candidate-controversy-4'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:fabien-roussel'), 'Débat à gauche après ses propos sur « un bon vin, une bonne viande »', 'En janvier 2022, pendant la campagne présidentielle, Fabien Roussel déclare qu''« un bon vin, une bonne viande, un bon fromage, c''est la gastronomie française » et défend l''accès de tous à une alimentation de qualité. La formule déclenche un débat au sein de la gauche sur l''articulation entre culture populaire, écologie et régimes alimentaires.', null, 'L''écologiste Sandrine Rousseau lui a notamment répondu que la gastronomie française inclut aussi « des raclettes suisses » et des sushis. Le directeur de campagne de Fabien Roussel a défendu des propos portant selon lui sur la hausse des salaires permettant d''accéder à une alimentation de qualité.', null, null, 'documented', '2026-09-11', null, 'Slate.fr', 'https://www.slate.fr/politique/2022-la-fabrique-dune-election/episode-38-fabien-roussel-viande-argument-electoral-carnisme-salvini-trump-johnson', 'media', 'published') on conflict (id) do nothing;
insert into candidate_controversies (id, candidate_id, title, summary, event_date, context, candidate_response, candidate_response_source_url, controversy_status, last_updated, next_review_at, source_name, source_url, source_type, status) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate_controversy:candidate-controversy-5'), uuid_generate_v5(uuid_ns_url(), 'poliscope:candidate:jean-luc-melenchon'), 'Qualification des attaques du 7 octobre 2023 et accusations d''antisémitisme', 'Le 7 octobre 2023, La France insoumise qualifie les attaques du Hamas contre Israël d''« offensive armée de forces palestiniennes » et estime qu''elles doivent être replacées « dans leur contexte », sans employer le terme d''attaque terroriste. La formulation, puis les prises de position de Jean-Luc Mélenchon dans les mois suivants — dont son refus de participer à la marche contre l''antisémitisme du 12 novembre 2023 — lui valent des accusations d''entretenir l''antisémitisme, qu''il conteste.', '2023-10-07', 'Le président du CRIF l''a qualifié d''« ennemi de la République » et sa position d''« abjecte ». Jean-Luc Mélenchon a justifié son absence à la marche du 12 novembre en la décrivant comme un rassemblement des « amis du soutien inconditionnel au massacre » à Gaza.', 'Il rappelle avoir appelé au cessez-le-feu dès le 7 octobre et affirme : « Nous n''avons jamais contesté le fait que des actes puissent être de nature terroriste. » Il maintient par ailleurs que l''action d''Israël à Gaza relève selon lui d''un « génocide » et non de la légitime défense.', 'https://www.franceinfo.fr/monde/proche-orient/israel-palestine/guerre-israel-hamas-jean-luc-melenchon-se-defend-face-aux-accusations-d-antisemitisme_6229194.html', 'disputed', '2026-09-11', null, 'Franceinfo', 'https://www.franceinfo.fr/monde/proche-orient/israel-palestine/guerre-israel-hamas-jean-luc-melenchon-se-defend-face-aux-accusations-d-antisemitisme_6229194.html', 'media', 'review_required') on conflict (id) do nothing;
